import { Inbox, FileSearch, Image, FileText, Search, UploadCloud, BookOpen, Lightbulb, Zap } from "lucide-react";
import { Empty, Button } from "antd";
import { useTranslation } from "react-i18next";
import type { TFunction } from "i18next";


export type EmptyStateType =
  | "default"
  | "search"
  | "figures"
  | "pdf"
  | "ocr"
  | "favorites"
  | "notes"
  | "citations"
  | "upload"
  | "firstRun"
  | "report";

interface GuideStep {
  icon: React.ReactNode;
  title: string;
  desc: string;
}

interface Action {
  label: string;
  onClick: () => void;
  /** 视觉权重：primary（主按钮）/ default（次按钮）/ text（文字按钮，默认） */
  variant?: "primary" | "default" | "text";
}

interface Props {
  type?: EmptyStateType;
  /** 主标题（粗体，显示在描述上方）。未提供时按 type 取 i18n 默认 */
  title?: string;
  /** 描述文案。未提供时按 type 取 i18n 默认 */
  description?: string;
  /** 主行动按钮（primary） */
  action?: Action;
  /** 次要行动按钮（显示在主按钮旁或下方） */
  secondaryAction?: Action;
  /** 引导步骤列表（仅 firstRun / ocr 等需要分步指引的状态使用） */
  guide?: {
    title: string;
    steps: GuideStep[];
  };
}

const ICONS: Record<EmptyStateType, React.ReactNode> = {
  default: <Inbox />,
  search: <FileSearch />,
  figures: <Image />,
  pdf: <FileText />,
  ocr: <Image />,
  favorites: <Inbox />,
  notes: <Inbox />,
  citations: <Inbox />,
  upload: <Inbox />,
  firstRun: <Search />,
  report: <BookOpen />,
};

/** 首次跑引导的 3 个默认步骤（调用方传 guide 时按 i18n 构建） */
const FIRST_RUN_DEFAULT_STEPS = (t: TFunction): GuideStep[] => [
  {
    icon: <UploadCloud />,
    title: t("home.firstRun.step1Title", "上传论文"),
    desc: t("home.firstRun.step1Desc", "拖拽 PDF/DOCX 或从 arXiv 导入"),
  },
  {
    icon: <Lightbulb />,
    title: t("home.firstRun.step2Title", "自动索引"),
    desc: t("home.firstRun.step2Desc", "系统自动提取元数据并建全文索引"),
  },
  {
    icon: <Zap />,
    title: t("home.firstRun.step3Title", "检索 & 问答"),
    desc: t("home.firstRun.step3Desc", "搜索、关系图、深度审稿一键可用"),
  },
];

function renderAction(action: Action) {
  const variant = action.variant ?? "primary";
  if (variant === "text") {
    return (
      <Button type="text" size="small" onClick={action.onClick} style={{ padding: "0 8px" }}>
        {action.label}
      </Button>
    );
  }
  return (
    <Button type={variant} onClick={action.onClick}>
      {action.label}
    </Button>
  );
}

export default function EmptyState({
  type = "default",
  title,
  description,
  action,
  secondaryAction,
  guide,
}: Props) {
  const { t } = useTranslation();

  // 默认标题/描述/引导按 type 取（对 firstRun/search/ocr/report 四态给丰富文案，其余保持原 fallback）
  const isContextual =
    type === "firstRun" || type === "search" || type === "ocr" || type === "report";
  const defaultTitle = isContextual
    ? type === "firstRun"
      ? t("home.firstRun.title", "欢迎来到 PaperForge")
      : type === "search"
        ? t("search.noResultsTitle", "没有匹配的论文")
        : type === "ocr"
          ? t("search.noOcrResultsTitle", "语义搜索未返回结果")
          : t("reports.emptyTitle", "暂无感悟报告")
    : undefined;
  const defaultDesc =
    description ??
    (type === "search"
      ? t("search.noResults")
      : type === "figures"
        ? t("figures.empty")
        : type === "firstRun"
          ? t("home.firstRun.desc", "导入或上传论文后，搜索、问答、深度审稿即刻可用")
          : type === "ocr"
            ? t("search.noOcrResultsDesc", "当前论文库尚未完成全文索引，语义检索暂时无结果")
            : type === "report"
              ? t(
                  "reports.emptyDesc",
                  "点击上方「提交感悟」按钮，或切换到「论文」标签开始导入论文。",
                )
              : t("common.noData"));

  // 首次跑引导：未传 guide 时按 type=firstRun 注入默认 3 步骤
  const effectiveGuide =
    guide ??
    (type === "firstRun"
      ? { title: t("home.firstRun.guideTitle", "3 步开始"), steps: FIRST_RUN_DEFAULT_STEPS(t) }
      : undefined);

  const icon = ICONS[type];

  return (
    <div
      style={{
        textAlign: "center",
        padding: "48px 16px",
        color: "var(--pf-text-placeholder)",
      }}
    >
      <Empty
        image={Empty.PRESENTED_IMAGE_SIMPLE}
        description={
          <div style={{ color: "var(--pf-text-secondary)", maxWidth: 480, margin: "0 auto" }}>
            {/* 图标：三态用更大的圆形容器 + 主色边框，其余保持原样 */}
            <div
              style={{
                fontSize: isContextual ? 32 : 24,
                marginBottom: 12,
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                width: isContextual ? 64 : undefined,
                height: isContextual ? 64 : undefined,
                borderRadius: isContextual ? "50%" : undefined,
                background: isContextual
                  ? "var(--pf-primary-soft, rgba(22,119,255,0.08))"
                  : undefined,
                border: isContextual ? "1px solid var(--pf-border-light)" : undefined,
                color: isContextual ? "var(--pf-primary)" : "var(--pf-text-placeholder)",
              }}
            >
              {icon}
            </div>

            {/* 主标题（仅三态或显式传入时显示，粗体） */}
            {(title ?? defaultTitle) && (
              <div
                style={{
                  fontSize: 16,
                  fontWeight: 600,
                  color: "var(--pf-text-primary)",
                  marginBottom: 6,
                }}
              >
                {title ?? defaultTitle}
              </div>
            )}

            {/* 描述 */}
            <div
              style={{
                fontSize: 14,
                lineHeight: 1.6,
                marginBottom: effectiveGuide || action || secondaryAction ? 16 : 0,
              }}
            >
              {defaultDesc}
            </div>

            {/* 行动按钮组 */}
            {(action || secondaryAction) && (
              <div
                style={{
                  display: "flex",
                  gap: 8,
                  justifyContent: "center",
                  flexWrap: "wrap",
                  marginBottom: effectiveGuide ? 20 : 0,
                }}
              >
                {action && renderAction(action)}
                {secondaryAction && renderAction(secondaryAction)}
              </div>
            )}

            {/* 引导步骤（首跑/索引缺失等场景） */}
            {effectiveGuide && (
              <div
                style={{
                  textAlign: "left",
                  marginTop: 8,
                  padding: "16px 20px",
                  background: "var(--pf-bg-tertiary)",
                  border: "1px solid var(--pf-border-light)",
                  borderRadius: 10,
                }}
              >
                <div
                  style={{
                    fontSize: 12,
                    fontWeight: 600,
                    color: "var(--pf-text-muted)",
                    marginBottom: 12,
                    textTransform: "uppercase",
                    letterSpacing: 0.5,
                  }}
                >
                  {effectiveGuide.title}
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                  {effectiveGuide.steps.map((step, i) => (
                    <div
                      key={i}
                      style={{
                        display: "flex",
                        gap: 12,
                        alignItems: "flex-start",
                        transition: "transform 0.15s ease",
                      }}
                    >
                      <div
                        style={{
                          flexShrink: 0,
                          display: "inline-flex",
                          alignItems: "center",
                          justifyContent: "center",
                          width: 32,
                          height: 32,
                          borderRadius: 8,
                          background: "var(--pf-primary-soft, rgba(22,119,255,0.08))",
                          color: "var(--pf-primary)",
                          fontSize: 16,
                        }}
                      >
                        {step.icon}
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div
                          style={{
                            fontSize: 13,
                            fontWeight: 600,
                            color: "var(--pf-text-primary)",
                            marginBottom: 2,
                          }}
                        >
                          {step.title}
                        </div>
                        <div
                          style={{ fontSize: 12, color: "var(--pf-text-muted)", lineHeight: 1.5 }}
                        >
                          {step.desc}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        }
      />
    </div>
  );
}

/** 便捷工厂：构建首次跑引导的 guide 对象（供调用方复用默认 i18n 文案） */
export function buildFirstRunGuide(t: TFunction) {
  return {
    title: t("home.firstRun.guideTitle", "3 步开始"),
    steps: FIRST_RUN_DEFAULT_STEPS(t),
  };
}

/** 便捷工厂：构建「索引缺失（语义搜索无结果）」引导的 guide 对象 */
export function buildOcrGuide(t: TFunction) {
  return {
    title: t("search.noOcrGuideTitle", "为什么没有结果？"),
    steps: [
      {
        icon: <BookOpen />,
        title: t("search.noOcrStep1Title", "全文索引未完成"),
        desc: t(
          "search.noOcrStep1Desc",
          "语义检索依赖论文的全文向量索引，新导入的论文需要时间完成索引",
        ),
      },
      {
        icon: <Search />,
        title: t("search.noOcrStep2Title", "切换关键词搜索"),
        desc: t("search.noOcrStep2Desc", "关键词搜索基于 FTS5，不依赖向量索引，立即可用"),
      },
    ],
  };
}

import { Copy, Trash2, Highlighter, History, BookOpen, Languages } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Button,
  ColorPicker,
  Empty,
  Input,
  List,
  message,
  Popover,
  Select,
  Space,
  Spin,
  Tabs,
  Tag,
  Tooltip,
} from "antd";

import { useTranslation } from "react-i18next";
import * as pdfjsLib from "pdfjs-dist";
// Vite 通过 ?url 后缀将 worker 文件作为 URL 资源导入
import workerUrl from "pdfjs-dist/build/pdf.worker.min.mjs?url";
import type { Paper, TranslationHistoryItem } from "@/api/types";
import type { HighlightColor } from "@/api/types";
import {
  deleteTranslationHistory,
  fetchTranslationHistory,
  saveTranslationHistory,
  translatePaperText,
} from "@/api/papers";

pdfjsLib.GlobalWorkerOptions.workerSrc = workerUrl;

// ---------------------------------------------------------------------------
// 类型与常量
// ---------------------------------------------------------------------------
/** 单条高亮记录（localStorage 主存储，与后端 PdfAnnotation 结构对齐） */
interface HighlightRecord {
  id: string;
  paperId: string;
  page: number;
  /** 归一化矩形列表：[x, y, w, h, ...]，坐标为 0-1 相对页面尺寸 */
  rects: number[];
  /** 选中的原文（便于列表展示与跳转） */
  text: string;
  color: string;
  note: string;
  createdAt: string;
}

const COLOR_PRESETS: { labelKey: string; value: HighlightColor }[] = [
  { labelKey: "pdf.colorYellow", value: "#FFEB3B" },
  { labelKey: "pdf.colorBlue", value: "#4FC3F7" },
  { labelKey: "pdf.colorGreen", value: "#81C784" },
  { labelKey: "pdf.colorPink", value: "#F48FB1" },
];

const STORAGE_KEY_PREFIX = "pf_pdf_highlights_";
const TRANSLATION_HISTORY_KEY_PREFIX = "pf_translation_history_";
const RENDER_SCALE = 1.4;
/** 初始渲染页数上限，超出后滚动到底部时懒加载更多 */
const INITIAL_PAGE_BATCH = 3;

interface PDFViewerProps {
  paper: Paper;
  /** PDF 数据源 URL；若为空则使用 arXiv 默认 PDF 链接 */
  pdfUrl: string;
  /** 初始页码（从 URL ?page= 传入） */
  initialPage?: number;
  /** 要高亮的文本（从 URL ?highlight= 传入） */
  highlightText?: string;
}

/** 生成 UUID（避免依赖额外包） */
function uuid(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }
  return `h_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}

/** 清洗 PDF 选中文本 */
function cleanSelectedText(raw: string): string {
  return raw.replace(/-\n/g, "").replace(/\n/g, " ").replace(/\s+/g, " ").trim();
}

interface TranslationPanelProps {
  original: string;
  targetLanguage: string;
  onTargetLanguageChange: (lang: string) => void;
  translating: boolean;
  translationResult: string;
  onTranslate: () => void;
  onCopy: () => void;
  history: TranslationHistoryItem[];
  onSelectHistory: (item: TranslationHistoryItem) => void;
  onDeleteHistory: (id: string) => void;
}

/** 翻译面板：源文/译文对照 + 目标语言选择 + 历史记录 */
function TranslationPanel({
  original,
  targetLanguage,
  onTargetLanguageChange,
  translating,
  translationResult,
  onTranslate,
  onCopy,
  history,
  onSelectHistory,
  onDeleteHistory,
}: TranslationPanelProps) {
  const { t } = useTranslation();
  const cleaned = original
    ? original.replace(/-\n/g, "").replace(/\n/g, " ").replace(/\s+/g, " ").trim()
    : "";
  return (
    <div style={{ padding: "4px 0" }}>
      <div style={{ marginBottom: 12 }}>
        <div style={{ fontSize: 12, color: "var(--pf-text-muted)", marginBottom: 6 }}>
          {t("pdf.targetLanguage", "目标语言")}
        </div>
        <Select
          value={targetLanguage}
          onChange={onTargetLanguageChange}
          size="small"
          style={{ width: "100%" }}
          options={[
            { value: "zh-CN", label: "简体中文" },
            { value: "zh-TW", label: "繁體中文" },
            { value: "en", label: "English" },
            { value: "ja", label: "日本語" },
            { value: "de", label: "Deutsch" },
            { value: "fr", label: "Français" },
          ]}
        />
      </div>

      <div style={{ marginBottom: 12 }}>
        <div style={{ fontSize: 12, color: "var(--pf-text-muted)", marginBottom: 6 }}>
          {t("pdf.originalText", "原文")}
        </div>
        <div
          style={{
            padding: 10,
            background: "var(--pf-bg-tertiary)",
            borderRadius: 6,
            fontSize: 13,
            color: "var(--pf-text-primary)",
            lineHeight: 1.6,
            maxHeight: 160,
            overflowY: "auto",
            whiteSpace: "pre-wrap",
            wordBreak: "break-word",
          }}
        >
          {cleaned || (
            <span style={{ color: "var(--pf-text-placeholder)" }}>
              {t("pdf.selectTextToTranslate", "请在 PDF 中选中文本")}
            </span>
          )}
        </div>
      </div>

      <Button
        type="primary"
        size="small"
        block
        loading={translating}
        disabled={!cleaned}
        onClick={onTranslate}
        style={{ marginBottom: 12 }}
      >
        {translating ? t("pdf.translating", "翻译中…") : t("pdf.translate", "翻译")}
      </Button>

      {translationResult && (
        <>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              marginBottom: 6,
            }}
          >
            <div style={{ fontSize: 12, color: "var(--pf-text-muted)" }}>
              {t("pdf.translationResult", "翻译结果")}
            </div>
            <Button size="small" type="text" icon={<Copy />} onClick={onCopy}>
              {t("common.copy", "复制")}
            </Button>
          </div>
          <div
            style={{
              padding: 10,
              background: "var(--pf-primary-soft)",
              borderRadius: 6,
              fontSize: 13,
              color: "var(--pf-text-primary)",
              lineHeight: 1.6,
              maxHeight: 240,
              overflowY: "auto",
              whiteSpace: "pre-wrap",
              wordBreak: "break-word",
            }}
          >
            {translationResult}
          </div>
        </>
      )}

      {history.length > 0 && (
        <div style={{ marginTop: 16 }}>
          <div
            style={{
              fontSize: 12,
              color: "var(--pf-text-muted)",
              marginBottom: 8,
              display: "flex",
              alignItems: "center",
              gap: 6,
            }}
          >
            <History />
            {t("pdf.translationHistory", "翻译历史")}
          </div>
          <List
            size="small"
            dataSource={history}
            renderItem={(item) => (
              <List.Item
                style={{ padding: "6px 4px", cursor: "pointer" }}
                onClick={() => onSelectHistory(item)}
                actions={[
                  <Button
                    key="delete"
                    size="small"
                    type="text"
                    danger
                    icon={<Trash2 />}
                    onClick={(e) => {
                      e.stopPropagation();
                      onDeleteHistory(item.id);
                    }}
                  />,
                ]}
              >
                <div style={{ width: "100%" }}>
                  <div
                    style={{
                      fontSize: 12,
                      color: "var(--pf-text-secondary)",
                      lineHeight: 1.4,
                      marginBottom: 2,
                    }}
                  >
                    {item.originalText.slice(0, 60)}
                    {item.originalText.length > 60 ? "…" : ""}
                  </div>
                  <div style={{ fontSize: 11, color: "var(--pf-text-placeholder)" }}>
                    {item.targetLanguage} ·{" "}
                    {(() => {
                      try {
                        return new Date(item.createdAt).toLocaleString("zh-CN", {
                          month: "2-digit",
                          day: "2-digit",
                          hour: "2-digit",
                          minute: "2-digit",
                        });
                      } catch {
                        return item.createdAt;
                      }
                    })()}
                  </div>
                </div>
              </List.Item>
            )}
          />
        </div>
      )}
    </div>
  );
}

/** 按 paperId 加载高亮记录（localStorage） */
function loadHighlights(paperId: string): HighlightRecord[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY_PREFIX + paperId);
    if (!raw) return [];
    const arr = JSON.parse(raw) as HighlightRecord[];
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

/** 保存高亮记录到 localStorage */
function saveHighlights(paperId: string, records: HighlightRecord[]): void {
  try {
    localStorage.setItem(STORAGE_KEY_PREFIX + paperId, JSON.stringify(records));
  } catch {
    // 存储满或被禁用时静默降级
  }
}

/** 按 paperId 加载翻译历史（localStorage 兜底） */
function loadTranslationHistoryLocal(paperId: string): TranslationHistoryItem[] {
  try {
    const raw = localStorage.getItem(TRANSLATION_HISTORY_KEY_PREFIX + paperId);
    if (!raw) return [];
    const arr = JSON.parse(raw) as TranslationHistoryItem[];
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

/** 保存翻译历史到 localStorage */
function saveTranslationHistoryLocal(paperId: string, items: TranslationHistoryItem[]): void {
  try {
    localStorage.setItem(TRANSLATION_HISTORY_KEY_PREFIX + paperId, JSON.stringify(items));
  } catch {
    // 存储满或被禁用时静默降级
  }
}

/**
 * 将 window.Selection 的若干 ClientRect 转换为相对页面容器的归一化矩形。
 * 返回扁平数组 [x, y, w, h, ...]，坐标范围 0-1，便于跨缩放比例复现高亮。
 */
function selectionToNormalizedRects(
  selection: Selection,
  pageEl: HTMLElement,
  pageWidth: number,
  pageHeight: number,
): number[] {
  const range = selection.getRangeAt(0);
  const rects = range.getClientRects();
  const containerRect = pageEl.getBoundingClientRect();
  const out: number[] = [];
  for (let i = 0; i < rects.length; i++) {
    const r = rects[i];
    const x = (r.left - containerRect.left) / pageWidth;
    const y = (r.top - containerRect.top) / pageHeight;
    const w = r.width / pageWidth;
    const h = r.height / pageHeight;
    // 过滤掉退化的零尺寸矩形
    if (w > 0.001 && h > 0.001) {
      out.push(x, y, w, h);
    }
  }
  return out;
}

export default function PDFViewer({ paper, pdfUrl, initialPage, highlightText }: PDFViewerProps) {
  const { t } = useTranslation();
  const containerRef = useRef<HTMLDivElement>(null);
  // 页面渲染容器映射：pageNo -> { wrapper, canvas, textLayerDiv, width, height }
  const pageRefs = useRef<Map<number, HTMLDivElement>>(new Map());
  const abortRef = useRef<boolean>(false);
  // 共享的 PDF 文档代理（加载一次，渲染与翻页共用，避免重复 getDocument）
  const pdfDocRef = useRef<pdfjsLib.PDFDocumentProxy | null>(null);
  // 待渲染页队列（totalPages 就绪后渲染前 N 页）
  const [pendingRender, setPendingRender] = useState(0);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>("");
  const [totalPages, setTotalPages] = useState(0);
  const [renderedPages, setRenderedPages] = useState(INITIAL_PAGE_BATCH);
  const [highlights, setHighlights] = useState<HighlightRecord[]>(() => loadHighlights(paper.id));
  const [currentColor, setCurrentColor] = useState<string>("#FFEB3B");
  const [activePage, setActivePage] = useState<number>(Math.max(1, initialPage || 1));
  // 临时高亮（来自 URL highlight 参数）
  const [tempHighlights, setTempHighlights] = useState<
    { page: number; rects: number[]; text: string }[]
  >([]);
  // 待确认的高亮（选中文本后弹出的 Popover 数据）
  const [pending, setPending] = useState<{
    page: number;
    rects: number[];
    text: string;
    note: string;
  } | null>(null);
  // WP-2.7: 浮动菜单当前视图（menu / highlight / translation）
  const [popoverView, setPopoverView] = useState<"menu" | "highlight" | "translation">("menu");

  // 每次选中文本时重置浮动菜单视图
  useEffect(() => {
    if (pending) setPopoverView("menu");
  }, [pending?.text]);
  // WP-2.7: 翻译状态
  const [translating, setTranslating] = useState(false);
  const [translationResult, setTranslationResult] = useState<string>("");
  const [translationOriginal, setTranslationOriginal] = useState<string>("");
  const [translationHistory, setTranslationHistory] = useState<TranslationHistoryItem[]>([]);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [sidebarTab, setSidebarTab] = useState<"highlights" | "translation">("highlights");
  const [targetLanguage, setTargetLanguage] = useState<string>(() => {
    try {
      return localStorage.getItem("pf_pdf_target_language") || "zh-CN";
    } catch {
      return "zh-CN";
    }
  });
  const isSelectingHistoryRef = useRef(false);
  const translationAbortRef = useRef(0);
  const initialNavDone = useRef(false);

  // 切换论文时重置深链导航标记
  useEffect(() => {
    initialNavDone.current = false;
  }, [pdfUrl]);

  // 同步高亮到 localStorage
  useEffect(() => {
    saveHighlights(paper.id, highlights);
  }, [highlights, paper.id]);

  // WP-2.7: 加载翻译历史（后端优先，失败时回退 localStorage）
  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const items = await fetchTranslationHistory(paper.id);
        if (!cancelled) setTranslationHistory(items);
      } catch {
        if (!cancelled) setTranslationHistory(loadTranslationHistoryLocal(paper.id));
      }
    };
    load();
    return () => {
      cancelled = true;
    };
  }, [paper.id]);

  // WP-2.7: 持久化目标语言偏好
  useEffect(() => {
    try {
      localStorage.setItem("pf_pdf_target_language", targetLanguage);
    } catch {
      // ignore
    }
  }, [targetLanguage]);

  // 加载 PDF（单次 getDocument，结果存入 pdfDocRef 供渲染复用）
  useEffect(() => {
    abortRef.current = false;
    setLoading(true);
    setError("");
    pageRefs.current.clear();
    setRenderedPages(INITIAL_PAGE_BATCH);
    setPendingRender(0);

    let task: pdfjsLib.PDFDocumentLoadingTask | null = null;

    const load = async () => {
      try {
        task = pdfjsLib.getDocument({
          url: pdfUrl,
          // 关闭 CMap 警告：使用标准字体路径
          cMapUrl: "https://unpkg.com/pdfjs-dist@4.7.76/cmaps/",
          cMapPacked: true,
        });
        const pdfDoc = await task.promise;
        if (abortRef.current) {
          pdfDoc.destroy().catch(() => {});
          return;
        }
        pdfDocRef.current = pdfDoc;
        setTotalPages(pdfDoc.numPages);
        setActivePage(1);
        // 触发首次渲染
        setPendingRender((n) => n + 1);
      } catch (e) {
        if (abortRef.current) return;
        const msg = e instanceof Error ? e.message : String(e);
        setError(t("pdf.loadFailed", { msg }));
      } finally {
        if (!abortRef.current) setLoading(false);
      }
    };
    load();

    return () => {
      abortRef.current = true;
      task?.destroy().catch(() => {});
      pdfDocRef.current?.destroy().catch(() => {});
      pdfDocRef.current = null;
    };
  }, [pdfUrl, t]);

  // 渲染指定页（canvas + text layer）
  const renderPage = useCallback(async (pageNo: number) => {
    const pdfDoc = pdfDocRef.current;
    if (!pdfDoc) return;
    const wrapper = pageRefs.current.get(pageNo);
    if (!wrapper) return;
    // 已渲染则跳过
    if (wrapper.dataset.rendered === "1") return;
    wrapper.dataset.rendered = "1";

    try {
      const page = await pdfDoc.getPage(pageNo);
      const viewport = page.getViewport({ scale: RENDER_SCALE });
      const canvas = wrapper.querySelector("canvas");
      const textDiv = wrapper.querySelector<HTMLElement>(".pf-pdf-text-layer");
      if (!canvas || !textDiv) return;

      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      // 高 DPI 渲染
      const outputScale = window.devicePixelRatio || 1;
      canvas.width = Math.floor(viewport.width * outputScale);
      canvas.height = Math.floor(viewport.height * outputScale);
      canvas.style.width = `${viewport.width}px`;
      canvas.style.height = `${viewport.height}px`;
      wrapper.style.width = `${viewport.width}px`;
      wrapper.style.height = `${viewport.height}px`;
      wrapper.dataset.pageWidth = String(viewport.width);
      wrapper.dataset.pageHeight = String(viewport.height);

      const transform = outputScale !== 1 ? [outputScale, 0, 0, outputScale, 0, 0] : undefined;
      await page.render({
        canvasContext: ctx,
        viewport,
        transform: transform as unknown as number[],
      }).promise;

      // 文本层（透明覆盖在 canvas 上，使文字可选）
      textDiv.style.width = `${viewport.width}px`;
      textDiv.style.height = `${viewport.height}px`;
      textDiv.innerHTML = "";
      const textContent = await page.getTextContent();
      const textLayer = new pdfjsLib.TextLayer({
        textContentSource: textContent,
        container: textDiv,
        viewport,
      });
      await textLayer.render();
    } catch (e) {
      // 单页失败不阻塞其他页
      console.warn(`渲染第 ${pageNo} 页失败`, e);
    }
  }, []);

  // 当 totalPages/renderedPages/pendingRender 变化时，渲染前 N 页
  useEffect(() => {
    if (totalPages === 0 || loading || !pdfDocRef.current) return;
    let cancelled = false;
    const run = async () => {
      const end = Math.min(renderedPages, totalPages);
      for (let i = 1; i <= end; i++) {
        if (cancelled) break;
        await renderPage(i);
      }
    };
    run();
    return () => {
      cancelled = true;
    };
  }, [renderedPages, totalPages, loading, pendingRender, renderPage]);

  // 深链：确保 initialPage 在渲染范围内
  useEffect(() => {
    if (!initialPage || totalPages === 0) return;
    if (initialPage > 0 && initialPage <= totalPages && renderedPages < initialPage) {
      setRenderedPages(initialPage);
    }
  }, [initialPage, totalPages, renderedPages]);

  // 深链：滚动到 initialPage 并高亮 highlightText
  useEffect(() => {
    if (loading || totalPages === 0 || initialNavDone.current) return;
    const target = initialPage && initialPage > 0 && initialPage <= totalPages ? initialPage : 1;
    const wrapper = pageRefs.current.get(target);
    if (wrapper) {
      wrapper.scrollIntoView({ behavior: "smooth", block: "start" });
      setActivePage(target);
      initialNavDone.current = true;
    }
  }, [loading, totalPages, initialPage]);

  // 深链：搜索并高亮 highlightText
  useEffect(() => {
    if (!highlightText || totalPages === 0 || loading) return;
    const searchAndHighlight = async () => {
      const pdfDoc = pdfDocRef.current;
      if (!pdfDoc) return;
      const matches: { page: number; rects: number[]; text: string }[] = [];
      for (let pageNo = 1; pageNo <= totalPages; pageNo++) {
        if (pageNo > renderedPages) break;
        const page = await pdfDoc.getPage(pageNo).catch(() => null);
        if (!page) continue;
        const textContent = await page.getTextContent();
        const fullText = textContent.items.map((item) => (item as any).str || "").join("");
        if (!fullText.includes(highlightText)) continue;
        // 计算高亮矩形：基于 textContent 中每个字符的位置
        const viewport = page.getViewport({ scale: RENDER_SCALE });
        const pageWidth = viewport.width;
        const pageHeight = viewport.height;
        const items = textContent.items as any[];
        const startIndex = fullText.indexOf(highlightText);
        if (startIndex < 0) continue;
        // 简单处理：只高亮第一个匹配片段
        const endIndex = startIndex + highlightText.length;
        let charIndex = 0;
        const rects: number[] = [];
        for (const item of items) {
          const str: string = item.str || "";
          const itemStart = charIndex;
          const itemEnd = charIndex + str.length;
          charIndex = itemEnd;
          if (itemEnd <= startIndex) continue;
          if (itemStart >= endIndex) break;
          const tx = item.transform || item.width !== undefined ? item : null;
          if (!tx) continue;
          const x = tx.transform[4] / pageWidth;
          const y = 1 - (tx.transform[5] + (tx.height || 12)) / pageHeight;
          const w = (tx.width || 10) / pageWidth;
          const h = (tx.height || 12) / pageHeight;
          rects.push(
            Math.max(0, Math.min(1, x)),
            Math.max(0, Math.min(1, y)),
            Math.max(0, Math.min(1, w)),
            Math.max(0, Math.min(1, h)),
          );
        }
        if (rects.length > 0) {
          matches.push({ page: pageNo, rects, text: highlightText });
          break;
        }
      }
      if (matches.length > 0) {
        setTempHighlights(matches);
        const first = matches[0];
        const wrapper = pageRefs.current.get(first.page);
        if (wrapper) {
          wrapper.scrollIntoView({ behavior: "smooth", block: "start" });
          setActivePage(first.page);
        }
      }
    };
    searchAndHighlight();
  }, [highlightText, totalPages, loading, renderedPages]);

  // 选中文本 → 弹出添加高亮 Popover
  const handleMouseUp = useCallback((pageNo: number, e: React.MouseEvent<HTMLDivElement>) => {
    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0 || sel.isCollapsed) {
      return;
    }
    const text = sel.toString().trim();
    if (!text) return;
    const wrapper = e.currentTarget;
    const pageWidth = Number(wrapper.dataset.pageWidth || 0);
    const pageHeight = Number(wrapper.dataset.pageHeight || 0);
    if (!pageWidth || !pageHeight) return;
    const rects = selectionToNormalizedRects(sel, wrapper, pageWidth, pageHeight);
    if (rects.length === 0) return;
    setPending({ page: pageNo, rects, text, note: "" });
  }, []);

  const confirmHighlight = () => {
    if (!pending) return;
    const rec: HighlightRecord = {
      id: uuid(),
      paperId: paper.id,
      page: pending.page,
      rects: pending.rects,
      text: pending.text,
      color: currentColor,
      note: pending.note,
      createdAt: new Date().toISOString(),
    };
    setHighlights((prev) => [rec, ...prev]);
    setPending(null);
    window.getSelection()?.removeAllRanges();
    message.success(t("pdf.highlightAdded"));
  };

  const cancelHighlight = () => {
    setPending(null);
    setTranslationResult("");
    setPopoverView("menu");
    window.getSelection()?.removeAllRanges();
  };

  // WP-2.7: 翻译选中文本
  const handleTranslate = useCallback(
    async (textToTranslate?: string, options?: { skipHistory?: boolean }) => {
      const sourceText = textToTranslate || pending?.text;
      if (!sourceText) return;
      const cleaned = cleanSelectedText(sourceText);
      if (!cleaned) return;

      const requestId = ++translationAbortRef.current;
      setTranslating(true);
      setTranslationResult("");
      setTranslationOriginal(cleaned);
      setPopoverView("translation");
      try {
        const text = cleaned.substring(0, 2000);
        const res = await translatePaperText(paper.id, text, targetLanguage);
        if (requestId !== translationAbortRef.current) return;
        setTranslationResult(res.translation);
        if (!options?.skipHistory) {
          await persistTranslation(cleaned, res.translation, targetLanguage);
        }
      } catch (e: any) {
        if (requestId !== translationAbortRef.current) return;
        message.error(e?.message || t("pdf.translationError", "翻译失败"));
      } finally {
        if (requestId === translationAbortRef.current) {
          setTranslating(false);
        }
      }
    },
    [paper.id, pending?.text, targetLanguage, t],
  );

  // WP-2.7: 持久化翻译记录到后端（失败时回退 localStorage)
  const persistTranslation = async (original: string, translated: string, lang: string) => {
    let backendId: string | undefined;
    try {
      const saved = await saveTranslationHistory(paper.id, {
        original_text: original,
        translated_text: translated,
        target_language: lang,
      });
      backendId = saved.id;
    } catch {
      // 后端保存失败时继续用 localStorage 兜底，保证离线/后端异常时仍可查看历史
    }
    const newItem: TranslationHistoryItem = {
      id: backendId || `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      paperId: paper.id,
      originalText: original,
      translatedText: translated,
      targetLanguage: lang,
      createdAt: new Date().toISOString(),
    };
    setTranslationHistory((prev) => {
      const next = [newItem, ...prev].slice(0, 50);
      saveTranslationHistoryLocal(paper.id, next);
      return next;
    });
  };

  // WP-2.7: 切换目标语言时，若存在当前原文则自动重译
  // handleTranslate 已用 useCallback 稳定；此处仅监听语言变化，避免依赖变化导致循环重译
  useEffect(() => {
    if (!translationOriginal) return;
    if (isSelectingHistoryRef.current) {
      isSelectingHistoryRef.current = false;
      return;
    }
    handleTranslate(translationOriginal);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [targetLanguage]);

  // WP-2.7: 从历史记录恢复翻译
  const handleSelectHistory = (item: TranslationHistoryItem) => {
    isSelectingHistoryRef.current = true;
    setTranslationOriginal(item.originalText);
    setTranslationResult(item.translatedText);
    setTargetLanguage(item.targetLanguage);
    setSidebarTab("translation");
    setSidebarOpen(true);
  };

  // WP-2.7: 删除历史记录
  const handleDeleteHistory = async (id: string) => {
    setTranslationHistory((prev) => {
      const next = prev.filter((item) => item.id !== id);
      saveTranslationHistoryLocal(paper.id, next);
      return next;
    });
    try {
      await deleteTranslationHistory(paper.id, id);
    } catch {
      // 后端删除失败时 localStorage 已同步
    }
  };

  const removeHighlight = (id: string) => {
    setHighlights((prev) => prev.filter((h) => h.id !== id));
  };

  const updateNote = (id: string, note: string) => {
    setHighlights((prev) => prev.map((h) => (h.id === id ? { ...h, note } : h)));
  };

  const jumpToHighlight = (rec: HighlightRecord) => {
    const wrapper = pageRefs.current.get(rec.page);
    if (wrapper) {
      wrapper.scrollIntoView({ behavior: "smooth", block: "center" });
      setActivePage(rec.page);
    }
  };

  const loadMorePages = () => {
    setRenderedPages((n) => Math.min(n + INITIAL_PAGE_BATCH, totalPages));
  };

  // 按页码分组高亮（便于渲染覆盖层）
  const highlightsByPage = useMemo(() => {
    const map = new Map<number, HighlightRecord[]>();
    for (const h of highlights) {
      if (!map.has(h.page)) map.set(h.page, []);
      map.get(h.page)!.push(h);
    }
    return map;
  }, [highlights]);

  const pendingStyle = useMemo(
    () => ({ background: currentColor }) as React.CSSProperties,
    [currentColor],
  );

  return (
    <div className="pf-pdf-viewer" style={{ display: "flex", gap: 12 }}>
      {/* 左侧：PDF 渲染区 */}
      <div
        ref={containerRef}
        className="pf-pdf-canvas-wrap"
        style={{
          flex: 1,
          minWidth: 0,
          maxHeight: 720,
          overflow: "auto",
          background: "var(--pf-bg-tertiary)",
          padding: 16,
          borderRadius: 8,
        }}
      >
        {/* 工具栏 */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            marginBottom: 12,
            position: "sticky",
            top: 0,
            background: "#ffffffee",
            padding: "6px 10px",
            borderRadius: 6,
            backdropFilter: "blur(6px)",
            zIndex: 5,
          }}
        >
          <Space size="small">
            <Highlighter style={{ color: currentColor }} />
            <span style={{ fontSize: 12, color: "var(--pf-text-secondary)" }}>
              {t("pdf.highlightColor")}
            </span>
            <ColorPicker
              value={currentColor}
              onChange={(c) => setCurrentColor(c.toHexString())}
              size="small"
              showText
              format="hex"
              presets={[
                {
                  label: t("pdf.presetLabel"),
                  colors: COLOR_PRESETS.map((p) => p.value),
                },
              ]}
            />
          </Space>
          <Space size="small">
            <Tag color="blue">
              {activePage}/{totalPages || "?"}
            </Tag>
            <Tag color="purple">
              {highlights.length} {t("pdf.highlightCount")}
            </Tag>
            <Button
              size="small"
              type={sidebarOpen ? "primary" : "default"}
              icon={<BookOpen />}
              onClick={() => setSidebarOpen((v) => !v)}
            >
              {t("pdf.sidebar", "高亮/翻译")}
            </Button>
          </Space>
        </div>

        {loading && (
          <div style={{ textAlign: "center", padding: "60px 0" }}>
            <Spin tip={t("pdf.loadingPdf")} />
          </div>
        )}
        {error && (
          <div style={{ color: "var(--pf-error)", padding: 24, textAlign: "center" }}>{error}</div>
        )}

        {!loading && !error && (
          <>
            {Array.from({ length: Math.min(renderedPages, totalPages) }).map((_, idx) => {
              const pageNo = idx + 1;
              return (
                <div
                  key={pageNo}
                  data-page={pageNo}
                  ref={(el) => {
                    if (el) pageRefs.current.set(pageNo, el);
                    else pageRefs.current.delete(pageNo);
                  }}
                  onMouseUp={(e) => handleMouseUp(pageNo, e)}
                  style={{
                    position: "relative",
                    margin: "0 auto 16px",
                    background: "var(--pf-bg-primary)",
                    boxShadow: "0 1px 4px rgba(0,0,0,0.1)",
                  }}
                >
                  {/* 页码角标 */}
                  <div
                    style={{
                      position: "absolute",
                      top: 4,
                      right: 8,
                      fontSize: 11,
                      color: "var(--pf-text-placeholder)",
                      zIndex: 4,
                    }}
                  >
                    {pageNo}
                  </div>
                  <canvas />
                  {/* 高亮覆盖层（位于 canvas 与 text layer 之间） */}
                  {(highlightsByPage.get(pageNo) || []).map((h) =>
                    Array.from({ length: h.rects.length / 4 }).map((__, ri) => {
                      const base = ri * 4;
                      const x = h.rects[base];
                      const y = h.rects[base + 1];
                      const w = h.rects[base + 2];
                      const hh = h.rects[base + 3];
                      return (
                        <Tooltip
                          key={`${h.id}-${ri}`}
                          title={h.note || h.text.slice(0, 80)}
                          placement="top"
                        >
                          <div
                            style={{
                              position: "absolute",
                              left: `${x * 100}%`,
                              top: `${y * 100}%`,
                              width: `${w * 100}%`,
                              height: `${hh * 100}%`,
                              background: h.color,
                              opacity: 0.4,
                              pointerEvents: "auto",
                              cursor: "pointer",
                              zIndex: 2,
                              mixBlendMode: "multiply",
                            }}
                            onClick={() => jumpToHighlight(h)}
                          />
                        </Tooltip>
                      );
                    }),
                  )}
                  {/* 临时深链高亮 */}
                  {tempHighlights
                    .filter((h) => h.page === pageNo)
                    .map((h, hi) =>
                      Array.from({ length: h.rects.length / 4 }).map((__, ri) => {
                        const base = ri * 4;
                        const x = h.rects[base];
                        const y = h.rects[base + 1];
                        const w = h.rects[base + 2];
                        const hh = h.rects[base + 3];
                        return (
                          <Tooltip key={`temp-${hi}-${ri}`} title={h.text} placement="top">
                            <div
                              style={{
                                position: "absolute",
                                left: `${x * 100}%`,
                                top: `${y * 100}%`,
                                width: `${w * 100}%`,
                                height: `${hh * 100}%`,
                                background: "#facc15",
                                opacity: 0.5,
                                pointerEvents: "none",
                                zIndex: 2,
                                mixBlendMode: "multiply",
                              }}
                            />
                          </Tooltip>
                        );
                      }),
                    )}
                  {/* 待确认高亮预览 */}
                  {pending && pending.page === pageNo && (
                    <Popover
                      title={
                        popoverView === "menu"
                          ? t("pdf.selectionActions", "选中文本")
                          : popoverView === "highlight"
                            ? t("pdf.addHighlight")
                            : t("pdf.translationResult", "翻译结果")
                      }
                      trigger="click"
                      open
                      onOpenChange={(o) => {
                        if (!o) cancelHighlight();
                      }}
                      content={
                        <div style={{ width: 280 }}>
                          {popoverView === "menu" && (
                            <>
                              <div
                                style={{
                                  padding: 8,
                                  background: "var(--pf-bg-tertiary)",
                                  borderRadius: 4,
                                  fontSize: 13,
                                  lineHeight: 1.5,
                                  color: "var(--pf-text-primary)",
                                  maxHeight: 120,
                                  overflowY: "auto",
                                  whiteSpace: "pre-wrap",
                                  wordBreak: "break-word",
                                  marginBottom: 10,
                                }}
                              >
                                {pending.text}
                              </div>
                              <Space wrap style={{ width: "100%" }}>
                                <Button
                                  size="small"
                                  icon={<Highlighter />}
                                  onClick={() => setPopoverView("highlight")}
                                >
                                  {t("pdf.highlight", "高亮")}
                                </Button>
                                <Button
                                  size="small"
                                  icon={<Languages />}
                                  onClick={() => handleTranslate()}
                                  loading={translating}
                                >
                                  {t("pdf.translate", "翻译")}
                                </Button>
                                <Button
                                  size="small"
                                  icon={<Copy />}
                                  onClick={() => {
                                    navigator.clipboard
                                      .writeText(pending.text)
                                      .then(() => message.success(t("common.copied")))
                                      .catch(() => message.error(t("common.copyFailed")));
                                  }}
                                >
                                  {t("common.copy", "复制")}
                                </Button>
                              </Space>
                            </>
                          )}

                          {popoverView === "highlight" && (
                            <>
                              <Input.TextArea
                                rows={3}
                                placeholder={t("pdf.annotationPlaceholder")}
                                value={pending.note}
                                onChange={(e) =>
                                  setPending((p) => (p ? { ...p, note: e.target.value } : p))
                                }
                              />
                              <div
                                style={{
                                  marginTop: 8,
                                  display: "flex",
                                  gap: 8,
                                  justifyContent: "flex-end",
                                  alignItems: "center",
                                }}
                              >
                                <Button size="small" onClick={() => setPopoverView("menu")}>
                                  {t("common.back")}
                                </Button>
                                <Button size="small" type="primary" onClick={confirmHighlight}>
                                  {t("pdf.confirmHighlight")}
                                </Button>
                              </div>
                              <div
                                style={{
                                  marginTop: 6,
                                  fontSize: 11,
                                  color: "var(--pf-text-placeholder)",
                                }}
                              >
                                {t("pdf.color")}
                                {currentColor}
                              </div>
                            </>
                          )}

                          {popoverView === "translation" && (
                            <>
                              <div
                                style={{
                                  padding: 8,
                                  background: "var(--pf-bg-tertiary)",
                                  borderRadius: 4,
                                  fontSize: 12,
                                  lineHeight: 1.5,
                                  color: "var(--pf-text-secondary)",
                                  maxHeight: 100,
                                  overflowY: "auto",
                                  whiteSpace: "pre-wrap",
                                  wordBreak: "break-word",
                                  marginBottom: 8,
                                }}
                              >
                                {translationOriginal}
                              </div>
                              <div
                                style={{
                                  padding: 8,
                                  background: "var(--pf-primary-soft)",
                                  borderRadius: 4,
                                  maxHeight: 160,
                                  overflowY: "auto",
                                  fontSize: 13,
                                  lineHeight: 1.5,
                                  color: "var(--pf-text-primary)",
                                  whiteSpace: "pre-wrap",
                                  wordBreak: "break-word",
                                }}
                              >
                                {translating ? (
                                  <Spin size="small" tip={t("pdf.translating")} />
                                ) : (
                                  translationResult || (
                                    <span style={{ color: "var(--pf-text-placeholder)" }}>
                                      {t("pdf.translationResult")}
                                    </span>
                                  )
                                )}
                              </div>
                              <div
                                style={{
                                  marginTop: 8,
                                  display: "flex",
                                  gap: 8,
                                  justifyContent: "flex-end",
                                }}
                              >
                                <Button
                                  size="small"
                                  icon={<Copy />}
                                  disabled={!translationResult}
                                  onClick={() => {
                                    navigator.clipboard
                                      .writeText(translationResult)
                                      .then(() => message.success(t("common.copied")))
                                      .catch(() => message.error(t("common.copyFailed")));
                                  }}
                                >
                                  {t("common.copy")}
                                </Button>
                                <Button size="small" onClick={() => setPopoverView("menu")}>
                                  {t("common.back")}
                                </Button>
                              </div>
                            </>
                          )}
                        </div>
                      }
                    >
                      <div
                        style={{
                          ...pendingStyle,
                          position: "absolute",
                          left: `${(pending.rects[0] || 0) * 100}%`,
                          top: `${(pending.rects[1] || 0) * 100}%`,
                          width: `${(pending.rects[2] || 0) * 100}%`,
                          height: `${(pending.rects[3] || 0) * 100}%`,
                          opacity: 0.5,
                          zIndex: 3,
                        }}
                      />
                    </Popover>
                  )}
                  {/* 文本层（透明，置于最上层以支持选中） */}
                  <div
                    className="pf-pdf-text-layer"
                    style={{
                      position: "absolute",
                      left: 0,
                      top: 0,
                      overflow: "hidden",
                      opacity: 1,
                      zIndex: 1,
                      // pdfjs TextLayer 需要文字透明但仍可选中
                      color: "transparent",
                    }}
                  />
                </div>
              );
            })}
            {/* 懒加载更多页 */}
            {renderedPages < totalPages && (
              <div style={{ textAlign: "center", padding: 16 }}>
                <Button onClick={loadMorePages} type="dashed">
                  {t("pdf.loadMore", { count: totalPages - renderedPages })}
                </Button>
              </div>
            )}
          </>
        )}
      </div>

      {/* 右侧：高亮/翻译侧边栏 */}
      {sidebarOpen && (
        <div
          className="pf-pdf-sidebar"
          style={{
            width: 320,
            flexShrink: 0,
            background: "var(--pf-bg-primary)",
            borderRadius: 8,
            padding: 12,
            maxHeight: 720,
            overflow: "auto",
            boxShadow: "0 1px 4px rgba(0,0,0,0.06)",
          }}
        >
          <Tabs
            activeKey={sidebarTab}
            onChange={(k) => setSidebarTab(k as "highlights" | "translation")}
            items={[
              {
                key: "highlights",
                label: t("pdf.highlightTab", "高亮"),
                children: <></>,
              },
              {
                key: "translation",
                label: t("pdf.translationTab", "翻译"),
                children: <></>,
              },
            ]}
          />
          {sidebarTab === "highlights" && (
            <div
              style={{
                fontWeight: 600,
                fontSize: 13,
                marginBottom: 8,
                color: "var(--pf-text-primary)",
              }}
            >
              {t("pdf.highlightsLabel", { count: highlights.length })}
            </div>
          )}
          {highlights.length === 0 ? (
            <Empty
              image={Empty.PRESENTED_IMAGE_SIMPLE}
              description={t("pdf.highlightHint")}
              style={{ margin: "24px 0" }}
            />
          ) : (
            <List
              size="small"
              dataSource={highlights}
              renderItem={(h) => (
                <List.Item style={{ padding: "8px 4px", alignItems: "flex-start" }}>
                  <div style={{ width: "100%" }}>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 6,
                        marginBottom: 4,
                      }}
                    >
                      <span
                        style={{
                          display: "inline-block",
                          width: 10,
                          height: 10,
                          borderRadius: 2,
                          background: h.color,
                          flexShrink: 0,
                        }}
                      />
                      <Tag style={{ marginRight: 0 }}>P{h.page}</Tag>
                      <span style={{ fontSize: 11, color: "var(--pf-text-placeholder)" }}>
                        {new Date(h.createdAt).toLocaleString("zh-CN", {
                          month: "2-digit",
                          day: "2-digit",
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </span>
                      <Button
                        size="small"
                        type="text"
                        danger
                        icon={<Trash2 />}
                        onClick={() => removeHighlight(h.id)}
                        style={{ marginLeft: "auto", padding: "0 4px" }}
                      />
                    </div>
                    <div
                      onClick={() => jumpToHighlight(h)}
                      style={{
                        fontSize: 12,
                        color: "var(--pf-text-secondary)",
                        cursor: "pointer",
                        lineHeight: 1.5,
                        marginBottom: 4,
                        display: "-webkit-box",
                        WebkitLineClamp: 2,
                        WebkitBoxOrient: "vertical",
                        overflow: "hidden",
                      }}
                    >
                      {h.text}
                    </div>
                    <Input.TextArea
                      rows={1}
                      size="small"
                      placeholder={t("pdf.annotationEditor")}
                      value={h.note}
                      onChange={(e) => updateNote(h.id, e.target.value)}
                      style={{ fontSize: 11 }}
                    />
                  </div>
                </List.Item>
              )}
            />
          )}
          {sidebarTab === "translation" && (
            <TranslationPanel
              original={translationOriginal}
              targetLanguage={targetLanguage}
              onTargetLanguageChange={setTargetLanguage}
              translating={translating}
              translationResult={translationResult}
              onTranslate={() => handleTranslate(translationOriginal)}
              onCopy={() => {
                if (!translationResult) return;
                navigator.clipboard
                  .writeText(translationResult)
                  .then(() => message.success(t("common.copied")))
                  .catch(() => message.error(t("common.copyFailed")));
              }}
              history={translationHistory}
              onSelectHistory={handleSelectHistory}
              onDeleteHistory={handleDeleteHistory}
            />
          )}
        </div>
      )}

      {/* pdfjs TextLayer 样式（透明文字、可选中） */}
      <style>{`
        .pf-pdf-text-layer span {
          color: transparent;
          -webkit-user-select: text;
          user-select: text;
        }
        .pf-pdf-text-layer ::selection {
          background: rgba(96, 165, 250, 0.35);
        }
      `}</style>
    </div>
  );
}

import { RefreshCw, Eye, Zap, CheckCircle, XCircle, Clock, FileText, Trash2, SquareMinus } from "lucide-react";
/**
 * ReflectionList 组件：分页列出 reflection 报告评审记录。
 *
 * 列：论文标题、状态、4 维评分（带 Progress）、平均分、判决、提交时间、操作
 * - 后端 reflection_result 已通过 _legacy_data_compat 兜底，
 *   前端读取时只需用 Number(score ?? 0) 即可，无需 ?. 防护
 * - 表格内「重新审稿」按钮复用 reflection/run 接口 + dedup 自愈（429/409 友好提示）
 * - SSE 进度通过 useTaskStore.subscribeSSE 订阅；列表通过 setInterval 5s 静默轮询活跃行
 */
import { useState, useEffect, useCallback, useRef } from "react";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import {
  Table,
  Tag,
  Button,
  Space,
  Tooltip,
  Typography,
  message,
  Empty,
  Progress,
  Spin,
  Popconfirm,
} from "antd";

import {
  listReflectionReviews,
  startReflectionReview,
  deleteReflectionReview,
  batchDeleteReflectionReviews,
  type ReflectionListItem,
} from "@/api/reflection";
import { useTaskStore } from "@/store/useTaskStore";
import ReflectionRadar from "./ReflectionRadar";

const { Title, Text } = Typography;

const ACTIVE_STATUSES = new Set(["pending", "running"]);

const VERDICT_COLORS: Record<string, string> = {
  well_done: "green",
  needs_evidence: "gold",
  needs_depth: "orange",
  rewrite_required: "red",
  "n/a": "default",
};

const VERDICT_LABELS: Record<string, string> = {
  well_done: "写得好",
  needs_evidence: "需补证据",
  needs_depth: "需深化",
  rewrite_required: "需重写",
  "n/a": "无评审",
};

const STATUS_COLORS: Record<string, string> = {
  pending: "default",
  running: "blue",
  completed: "green",
  failed: "red",
};

const STATUS_LABELS: Record<string, string> = {
  pending: "等待",
  running: "进行中",
  completed: "已完成",
  failed: "失败",
};

const STATUS_ICONS: Record<string, React.ReactNode> = {
  pending: <Clock />,
  running: <RefreshCw className="pf-spin" />,
  completed: <CheckCircle />,
  failed: <XCircle />,
};

interface ReflectionListProps {
  /** 是否在 HomePage 内嵌展示（紧凑模式） */
  compact?: boolean;
  /** 显示行数限制（compact 模式默认 5） */
  pageSize?: number;
}

export default function ReflectionList({
  compact = false,
  pageSize: initialPageSize = 20,
}: ReflectionListProps) {
  const navigate = useNavigate();
  const { subscribeSSE } = useTaskStore();
  const { t } = useTranslation();
  const [data, setData] = useState<ReflectionListItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize] = useState(compact ? Math.min(initialPageSize, 5) : initialPageSize);
  const [loading, setLoading] = useState(false);
  const [restartingIds, setRestartingIds] = useState<Set<string>>(new Set());
  // 批量选择：useState<string[]>（rowKey="id" → ReflectionListItem.id）
  // compact 模式禁用（嵌入式 HomePage 控件不暴露批量操作，避免误操作）
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [batchDeleting, setBatchDeleting] = useState(false);
  const dataRef = useRef(data);
  // SSE 订阅 cleanup Set：每次重评时取消上一个订阅，防内存泄露
  const restartUnsubsRef = useRef<Set<() => void>>(new Set());

  useEffect(() => {
    dataRef.current = data;
  }, [data]);

  // 卸载时取消所有进行中的 SSE 订阅
  useEffect(() => {
    return () => {
      restartUnsubsRef.current.forEach((unsub) => unsub());
      restartUnsubsRef.current.clear();
    };
  }, []);

  const fetchList = useCallback(
    async (p: number, silent = false) => {
      if (!silent) setLoading(true);
      try {
        const res = await listReflectionReviews(pageSize, (p - 1) * pageSize);
        setData(res.items);
        setTotal(res.total);
      } catch {
        if (!silent) message.error("获取 reflection 列表失败");
      } finally {
        if (!silent) setLoading(false);
      }
    },
    [pageSize],
  );

  useEffect(() => {
    fetchList(page);
    // 进行中的 reflection 评审每 5 秒静默轮询
    const timer = setInterval(() => {
      if (dataRef.current.some((d) => ACTIVE_STATUSES.has(d.status))) {
        fetchList(page, true);
      }
    }, 5000);
    return () => clearInterval(timer);
  }, [page, fetchList]);

  const handleDelete = useCallback(
    async (reviewId: number) => {
      try {
        await deleteReflectionReview(String(reviewId));
        message.success("评审记录已删除");
        fetchList(page);
      } catch (e: any) {
        message.error(e?.response?.data?.detail || "删除失败");
      }
    },
    [fetchList, page],
  );

  // 批量删除：调用 POST /api/depth/reviews/batch-delete，参数为 review_ids 列表
  const handleBatchDelete = useCallback(async () => {
    if (selectedIds.length === 0) return;
    setBatchDeleting(true);
    try {
      const res = await batchDeleteReflectionReviews(selectedIds);
      if (res.failed_ids && res.failed_ids.length > 0) {
        message.warning(
          `部分删除失败：成功 ${res.deleted_count} 条，失败 ${res.failed_ids.length} 条`,
          4,
        );
      } else {
        message.success(`已批量删除 ${res.deleted_count} 条评审记录`);
      }
      setSelectedIds([]);
      fetchList(page, true);
    } catch (e: any) {
      message.error(e?.response?.data?.detail || "批量删除失败");
    } finally {
      setBatchDeleting(false);
    }
  }, [selectedIds, fetchList, page]);

  const handleRestart = useCallback(
    async (paperId: string) => {
      setRestartingIds((prev) => new Set(prev).add(paperId));
      try {
        const res = await startReflectionReview(paperId);
        message.success(`重评已提交（task_id=${res.task_id}）`);

        // 订阅 SSE 进度（onUpdate 静默刷新列表以感知轮询回退时的进度）
        const unsub = subscribeSSE(
          res.task_id,
          () => {
            fetchList(page, true);
          },
          () => {
            fetchList(page, true);
            message.success("重评完成");
            unsub();
            restartUnsubsRef.current.delete(unsub);
          },
          (info) => {
            fetchList(page, true);
            message.error(info.error || "重评失败");
            unsub();
            restartUnsubsRef.current.delete(unsub);
          },
        );
        restartUnsubsRef.current.add(unsub);
      } catch (e: any) {
        const status = e?.response?.status;
        const detail = e?.response?.data?.detail || e?.message || "重评启动失败";
        if (status === 409) {
          const firstLine = String(detail).split("\n")[0];
          message.warning(`已有进行中的任务。${firstLine}`, 4);
        } else if (status === 400) {
          // 例如：报告无全文
          message.error(detail);
        } else {
          message.error(detail);
        }
        fetchList(page, true);
      } finally {
        setRestartingIds((prev) => {
          const next = new Set(prev);
          next.delete(paperId);
          return next;
        });
      }
    },
    [fetchList, page, subscribeSSE],
  );

  const columns = [
    {
      title: "报告",
      dataIndex: "paper_title",
      key: "paper_title",
      ellipsis: true,
      render: (t: string, record: ReflectionListItem) => (
        <Space size={4} direction="vertical">
          <span>{t || "(未命名)"}</span>
          <Text type="secondary" style={{ fontSize: 11 }} copyable={{ text: record.paper_id }}>
            {record.paper_id}
          </Text>
        </Space>
      ),
    },
    {
      title: "状态",
      dataIndex: "status",
      key: "status",
      width: 100,
      render: (s: string) => (
        <Tag icon={STATUS_ICONS[s]} color={STATUS_COLORS[s]}>
          {STATUS_LABELS[s] || s}
        </Tag>
      ),
    },
    {
      title: t("reflection.list.scoresColumn"),
      key: "scores",
      width: 150,
      align: "center" as const,
      render: (_: any, record: ReflectionListItem) => (
        <ReflectionRadar scores={record.scores} size={110} />
      ),
    },
    {
      title: "平均分",
      dataIndex: ["scores", "average"],
      key: "average",
      width: 120,
      sorter: false,
      render: (avg: number | null, record: ReflectionListItem) => {
        if (avg == null) return <Text type="secondary">-</Text>;
        const pct = Math.round(avg * 100);
        const hasFidelity = record.fidelity != null;
        return (
          <div>
            <Tooltip
              title={
                hasFidelity
                  ? `4 维均分 ${pct}% | 忠实度 ${Math.round((record.fidelity ?? 0) * 100)}%`
                  : `${pct}%`
              }
            >
              <Progress
                percent={pct}
                size="small"
                showInfo={false}
                strokeColor={pct >= 70 ? "#52c41a" : pct >= 50 ? "#faad14" : "#ff4d4f"}
                style={{ width: 60, marginBottom: 2 }}
              />
              <div>
                <Text style={{ fontSize: 12, fontWeight: 600 }}>{pct}%</Text>
                {hasFidelity && (
                  <Tooltip
                    title={`忠实度 ${Math.round((record.fidelity ?? 0) * 100)}%（报告 vs 原论文）`}
                  >
                    <Tag
                      color={
                        (record.fidelity ?? 0) >= 0.6
                          ? "green"
                          : (record.fidelity ?? 0) >= 0.35
                            ? "gold"
                            : "red"
                      }
                      style={{ fontSize: 10, padding: "0 4px", marginLeft: 4, lineHeight: "18px" }}
                    >
                      F{Math.round((record.fidelity ?? 0) * 100)}
                    </Tag>
                  </Tooltip>
                )}
              </div>
            </Tooltip>
          </div>
        );
      },
    },
    {
      title: "判决",
      dataIndex: "verdict",
      key: "verdict",
      width: 110,
      render: (v: string | null, record: ReflectionListItem) => {
        if (!v) return <Text type="secondary">-</Text>;
        return (
          <Tooltip title={record.verdict_reason || VERDICT_LABELS[v] || v}>
            <Tag color={VERDICT_COLORS[v] || "default"}>{VERDICT_LABELS[v] || v}</Tag>
          </Tooltip>
        );
      },
    },
    {
      title: "证据/观点",
      key: "evidence",
      width: 100,
      align: "center" as const,
      render: (_: any, record: ReflectionListItem) => (
        <Tooltip
          title={
            <div>
              <div>证据片段: {record.effective_evidence_count}</div>
              <div>核心观点: {record.claims_count}</div>
            </div>
          }
        >
          <Text style={{ fontSize: 12 }}>
            {record.effective_evidence_count}/{record.claims_count}
          </Text>
        </Tooltip>
      ),
    },
    {
      title: "完成时间",
      dataIndex: "completed_at",
      width: 150,
      render: (t: string | null) => (t ? new Date(t).toLocaleString() : "-"),
    },
    {
      title: "操作",
      key: "actions",
      width: 170,
      fixed: "right" as const,
      render: (_: any, record: ReflectionListItem) => {
        const isActive = ACTIVE_STATUSES.has(record.status);
        const isRestarting = restartingIds.has(record.paper_id);
        return (
          <Space size={4}>
            <Button
              size="small"
              icon={<Eye />}
              onClick={() => navigate(`/reflection/result/${record.paper_id}`)}
            >
              查看
            </Button>
            <Tooltip
              title={
                isActive
                  ? `${record.paper_id} 正在评审中，请等待完成后再重评`
                  : "重新发起 reflection 评审"
              }
            >
              <Button
                size="small"
                icon={<Zap />}
                loading={isRestarting}
                disabled={isActive}
                onClick={() => handleRestart(record.paper_id)}
              >
                重评
              </Button>
            </Tooltip>
            <Popconfirm
              title="确定删除该评审记录？"
              description="此操作不可撤销"
              onConfirm={(e) => {
                e?.stopPropagation();
                handleDelete(record.id);
              }}
              onCancel={(e) => e?.stopPropagation()}
              okText="删除"
              cancelText="取消"
              okButtonProps={{ danger: true }}
            >
              <Button
                size="small"
                danger
                icon={<Trash2 />}
                onClick={(e) => e.stopPropagation()}
              >
                删除
              </Button>
            </Popconfirm>
          </Space>
        );
      },
    },
  ];

  // compact 模式仅保留「标题 / 状态 / 平均分 / 判决 / 操作」5 列；按 column.key
  // 过滤而非按 i18n title，避免依赖杕抹中文（避免 i18n key 未来跨语言影响布局）
  const COMPACT_COLUMN_KEYS = new Set(["paper_title", "status", "average", "verdict", "actions"]);

  if (compact) {
    return (
      <div>
        <Spin spinning={loading}>
          {data.length === 0 ? (
            <Empty
              image={Empty.PRESENTED_IMAGE_SIMPLE}
              description={t("reflection.list.empty")}
              style={{ padding: "24px 0" }}
            />
          ) : (
            <Table
              dataSource={data}
              rowKey="id"
              size="small"
              pagination={false}
              columns={columns.filter((c) => COMPACT_COLUMN_KEYS.has(String(c.key)))}
            />
          )}
        </Spin>
      </div>
    );
  }

  return (
    <div>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: 12,
          flexWrap: "wrap",
          gap: 12,
        }}
      >
        <Space>
          <Title level={4} style={{ margin: 0 }}>
            <FileText style={{ color: "var(--pf-primary)", marginRight: 8 }} />
            {t("reflection.list.title")}
          </Title>
          <Text type="secondary" style={{ fontSize: 13 }}>
            按平均分降序 · 有正在评审的报告每 5 秒自动刷新
          </Text>
        </Space>
        <Space size={8}>
          <Text type="secondary" style={{ fontSize: 13 }}>
            已选 <strong>{selectedIds.length}</strong> 条
          </Text>
          <Popconfirm
            title={`确定批量删除 ${selectedIds.length} 条评审记录？`}
            description="此操作不可撤销"
            okText="批量删除"
            cancelText="取消"
            okButtonProps={{ danger: true }}
            disabled={selectedIds.length === 0 || batchDeleting}
            onConfirm={(e) => {
              e?.stopPropagation();
              handleBatchDelete();
            }}
            onCancel={(e) => e?.stopPropagation()}
          >
            <Button
              danger
              icon={<Trash2 />}
              loading={batchDeleting}
              disabled={selectedIds.length === 0}
              onClick={(e) => e.stopPropagation()}
            >
              批量删除
            </Button>
          </Popconfirm>
          <Button
            size="small"
            icon={<SquareMinus />}
            disabled={selectedIds.length === 0}
            onClick={() => setSelectedIds([])}
          >
            清空选择
          </Button>
          <Button icon={<RefreshCw />} onClick={() => fetchList(page)}>
            刷新
          </Button>
        </Space>
      </div>
      <Table
        dataSource={data}
        rowKey="id"
        loading={loading}
        scroll={{ x: 1100 }}
        rowSelection={{
          selectedRowKeys: selectedIds,
          onChange: (keys: React.Key[]) => setSelectedIds(keys.map(String)),
          getCheckboxProps: (record: ReflectionListItem) => ({
            disabled: ACTIVE_STATUSES.has(record.status),
            title: ACTIVE_STATUSES.has(record.status)
              ? `${record.paper_id} 正在评审中，无法勾选`
              : "勾选后可批量删除该条评审记录",
          }),
        }}
        pagination={{
          current: page,
          total,
          pageSize,
          onChange: (p) => setPage(p),
          showTotal: (t) => `共 ${t} 条`,
        }}
        onRow={(record) => ({
          onClick: () => navigate(`/reflection/result/${record.paper_id}`),
          style: { cursor: "pointer" },
        })}
        columns={columns}
        expandable={{
          rowExpandable: (record) =>
            record.status === "failed" || (record.verdict_reason ?? "").length > 0,
          expandedRowRender: (record) => (
            <div
              style={{ padding: "8px 16px", background: "var(--pf-bg-secondary)", borderRadius: 6 }}
            >
              <Text type="secondary" style={{ fontSize: 12 }}>
                判决依据：
              </Text>
              <div style={{ fontSize: 13, marginTop: 4 }}>
                {record.verdict_reason || "（无说明）"}
              </div>
              {record.error_message && (
                <Text type="danger" style={{ fontSize: 12, marginTop: 8, display: "block" }}>
                  ⚠️ 错误：{record.error_message}
                </Text>
              )}
            </div>
          ),
        }}
      />
    </div>
  );
}

import { RefreshCw, CheckCircle, XCircle, Clock, FileSearch, Zap, ArrowLeft, Lightbulb, FlaskConical, Rocket, Link, BadgeCheck, TriangleAlert } from "lucide-react";
/**
 * ReflectionResultView 组件：单条 reflection 评审详情页。
 *
 * 路由：/reflection/result/:paperId
 * 展示：4 维评分（带 Progress）、核心观点/证据池、总结、判决理由、verdict
 * 行为：状态为 running/pending 时每 3 秒轮询刷新
 */
import { useState, useEffect, useCallback, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Spin,
  Card,
  Tag,
  Progress,
  Typography,
  Space,
  Button,
  Alert,
  Descriptions,
  Empty,
  Table,
  Tooltip,
  message,
  Collapse,
} from "antd";

import {
  getReflectionResult,
  startReflectionReview,
  type ReflectionResultResponse,
  type FidelityAnchor,
} from "@/api/reflection";
import { useTaskStore } from "@/store/useTaskStore";

const { Title, Text, Paragraph } = Typography;

const VERDICT_COLORS: Record<string, string> = {
  well_done: "green",
  needs_evidence: "gold",
  needs_depth: "orange",
  rewrite_required: "red",
  "n/a": "default",
};

const VERDICT_LABELS: Record<string, string> = {
  well_done: "写得好 Well Done",
  needs_evidence: "需补证据 Needs Evidence",
  needs_depth: "需深化 Needs Depth",
  rewrite_required: "需重写 Rewrite Required",
  "n/a": "无评审 N/A",
};

const STATUS_ICONS: Record<string, React.ReactNode> = {
  pending: <Clock />,
  running: <RefreshCw className="pf-spin" />,
  completed: <CheckCircle />,
  failed: <XCircle />,
};

const ACTIVE_STATUSES = new Set(["pending", "running"]);

function ScoreBar({
  label,
  score,
  color = "#1677ff",
  icon,
}: {
  label: string;
  score: number;
  color?: string;
  icon?: React.ReactNode;
}) {
  const safe = Number(score ?? 0);
  const pct = Math.round(safe * 100);
  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
        <Space>
          {icon}
          <Text type="secondary">{label}</Text>
        </Space>
        <Text strong>{pct}%</Text>
      </div>
      <Progress percent={pct} strokeColor={color} showInfo={false} size="small" />
    </div>
  );
}

export default function ReflectionResultView() {
  const { paperId } = useParams<{ paperId: string }>();
  const navigate = useNavigate();
  const { subscribeSSE } = useTaskStore();
  const [result, setResult] = useState<ReflectionResultResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [restarting, setRestarting] = useState(false);
  const fetchingRef = useRef(false);

  const fetchResult = useCallback(async () => {
    if (!paperId) return;
    if (fetchingRef.current) return;
    fetchingRef.current = true;
    setLoading(true);
    setError(null);
    try {
      const res = await getReflectionResult(paperId);
      setResult(res);
    } catch (e: any) {
      if (e?.response?.status === 404) {
        setError("该论文暂无 reflection 评审结果");
      } else {
        setError(e?.response?.data?.detail || "获取评审结果失败");
      }
    } finally {
      setLoading(false);
      fetchingRef.current = false;
    }
  }, [paperId]);

  useEffect(() => {
    if (!paperId) return;
    fetchResult();
    const timer = setInterval(() => {
      if (result && ACTIVE_STATUSES.has(result.status)) {
        fetchResult();
      }
    }, 3000);
    return () => clearInterval(timer);
  }, [paperId, result?.status, fetchResult]);

  const handleRestart = async () => {
    if (!paperId) return;
    setRestarting(true);
    try {
      const res = await startReflectionReview(paperId);
      message.success(`重评已提交（task_id=${res.task_id}）`);
      subscribeSSE(
        res.task_id,
        undefined,
        () => {
          fetchResult();
          message.success("重评完成");
        },
        (info) => {
          fetchResult();
          message.error(info.error || "重评失败");
        },
      );
    } catch (e: any) {
      const status = e?.response?.status;
      const detail = e?.response?.data?.detail || e?.message || "重评失败";
      if (status === 409) {
        const firstLine = String(detail).split("\n")[0];
        message.warning(`已有进行中的任务。${firstLine}`, 4);
      } else {
        message.error(detail);
      }
    } finally {
      setRestarting(false);
    }
  };

  if (loading && !result) {
    return <Spin size="large" style={{ display: "block", margin: "100px auto" }} />;
  }

  if (error && !result) {
    return (
      <div style={{ maxWidth: 700, margin: "60px auto", textAlign: "center" }}>
        <Empty description={error}>
          <Button
            type="primary"
            icon={<Zap />}
            onClick={handleRestart}
            loading={restarting}
          >
            启动 reflection 评审
          </Button>
        </Empty>
      </div>
    );
  }

  if (!result) return null;

  const r = result.result;
  const scores = r?.scores;
  const avg = Number(scores?.average ?? 0);
  const isActive = ACTIVE_STATUSES.has(result.status);

  return (
    <div style={{ maxWidth: 900, margin: "0 auto", padding: "24px 16px" }}>
      {/* 顶部状态栏 */}
      <Space style={{ marginBottom: 16 }}>
        <Button
          size="small"
          icon={<ArrowLeft />}
          onClick={() => navigate("/depth-v4?tab=report")}
        >
          返回报告列表
        </Button>
        {STATUS_ICONS[result.status]}
        <Text>
          {result.status === "running"
            ? "评审中..."
            : result.status === "completed"
              ? "评审完成"
              : result.status === "failed"
                ? "评审失败"
                : "等待中"}
        </Text>
        {isActive && (
          <Button size="small" icon={<RefreshCw />} onClick={fetchResult}>
            刷新
          </Button>
        )}
        {!isActive && (
          <Button
            size="small"
            icon={<Zap />}
            loading={restarting}
            onClick={handleRestart}
          >
            重新评审
          </Button>
        )}
      </Space>

      {result.status === "failed" && (
        <Alert
          type="error"
          message="评审失败"
          description={result.error_message}
          showIcon
          style={{ marginBottom: 16 }}
        />
      )}

      {result.status === "running" && (
        <Alert
          type="info"
          message="reflection 评审进行中，请稍候..."
          showIcon
          style={{ marginBottom: 16 }}
        />
      )}

      {result.status === "completed" && r && (
        <>
          {/* 综合分 + 判决 */}
          <Card style={{ marginBottom: 16, textAlign: "center" }}>
            <Title level={2} style={{ marginBottom: 4 }}>
              综合得分 {((r.analysis_v2?.average ?? avg) * 100).toFixed(0)}%
            </Title>
            <Tag
              color={VERDICT_COLORS[r.verdict] || "default"}
              style={{ fontSize: 16, padding: "4px 16px" }}
            >
              {VERDICT_LABELS[r.verdict] || r.verdict}
            </Tag>
            {r.verdict_reason && (
              <Paragraph type="secondary" style={{ marginTop: 12, fontSize: 13 }}>
                {r.verdict_reason}
              </Paragraph>
            )}
            {/* 忠实度过低导致的 rewrite_required 警告 */}
            {r.verdict === "rewrite_required" && r.fidelity != null && r.fidelity < 0.3 && (
              <Alert
                type="warning"
                showIcon
                icon={<TriangleAlert />}
                message={`忠实度过低（${Math.round(r.fidelity * 100)}%）：报告内容与原论文匹配度不足 30%，大量论点疑似编造，系统判定需重写`}
                style={{ marginTop: 12, textAlign: "left" }}
              />
            )}
          </Card>

          {/* 5 维评分（analysis_v2）或 4 维评分（旧版） */}
          <Card
            title={r.analysis_v2 ? "5 维评分（含忠实度）" : "4 维评分"}
            style={{ marginBottom: 16 }}
          >
            <ScoreBar
              label="理解准确性"
              score={(r.analysis_v2?.understanding_accuracy ?? scores?.understanding_accuracy) || 0}
              color="#1677ff"
              icon={<FlaskConical />}
            />
            <ScoreBar
              label="分析深度"
              score={(r.analysis_v2?.analysis_depth ?? scores?.analysis_depth) || 0}
              color="#722ed1"
              icon={<Lightbulb />}
            />
            <ScoreBar
              label="创新性见解"
              score={(r.analysis_v2?.innovative_insights ?? scores?.innovative_insights) || 0}
              color="#fa8c16"
              icon={<Rocket />}
            />
            <ScoreBar
              label="证据支撑"
              score={(r.analysis_v2?.evidence_support ?? scores?.evidence_support) || 0}
              color="#52c41a"
              icon={<Link />}
            />
            {(() => {
              const fs = r.fidelity_status;
              const hasScore = (r.analysis_v2?.fidelity ?? r.fidelity) != null;
              if (fs === "too_short") {
                return (
                  <div style={{ margin: "4px 0 12px" }}>
                    <Text type="secondary" style={{ fontSize: 13 }}>
                      忠实度：正文过短，无法计算
                    </Text>
                    <div
                      style={{ fontSize: 12, color: "var(--pf-text-placeholder)", marginTop: 2 }}
                    >
                      报告正文解析后不足 100 字，比对无意义
                    </div>
                  </div>
                );
              }
              if (fs === "no_paper") {
                return (
                  <div style={{ margin: "4px 0 12px" }}>
                    <Text type="secondary" style={{ fontSize: 13 }}>
                      忠实度：未绑定原论文，无法计算
                    </Text>
                    <div
                      style={{ fontSize: 12, color: "var(--pf-text-placeholder)", marginTop: 2 }}
                    >
                      未识别 / 绑定到原论文，无法比对
                    </div>
                  </div>
                );
              }
              if (fs === "degraded_model") {
                return (
                  <ScoreBar
                    label="忠实度（退化模型，仅供参考）"
                    score={r.analysis_v2?.fidelity ?? r.fidelity ?? 0}
                    color="#faad14"
                    icon={<BadgeCheck />}
                  />
                );
              }
              if (hasScore) {
                return (
                  <ScoreBar
                    label={`忠实度${r.analysis_v2 ? "" : "（与原论文比对）"}`}
                    score={r.analysis_v2?.fidelity ?? r.fidelity ?? 0}
                    color={(() => {
                      const f = r.analysis_v2?.fidelity ?? r.fidelity ?? 0;
                      return f >= 0.4 ? "#52c41a" : f >= 0.3 ? "#faad14" : "#ff4d4f";
                    })()}
                    icon={<BadgeCheck />}
                  />
                );
              }
              return (
                <div style={{ margin: "4px 0 12px" }}>
                  <Text type="secondary" style={{ fontSize: 13 }}>
                    忠实度（与原论文比对）：未计算
                  </Text>
                  <div style={{ fontSize: 12, color: "var(--pf-text-placeholder)", marginTop: 2 }}>
                    未识别 / 绑定到原论文，无法比对
                  </div>
                </div>
              );
            })()}
            {r.analysis_v2 && (
              <div style={{ textAlign: "center", marginTop: 8 }}>
                <Text type="secondary" style={{ fontSize: 12 }}>
                  5 维均权综合分：{Math.round(r.analysis_v2.average * 100)}%（含忠实度维度）
                </Text>
              </div>
            )}
          </Card>

          {/* 忠实度锚点句（fidelity_anchors） */}
          {r.fidelity_anchors && r.fidelity_anchors.length > 0 && (
            <Collapse
              style={{ marginBottom: 16 }}
              items={[
                {
                  key: "fidelity-anchors",
                  label: (
                    <Space>
                      <BadgeCheck />
                      忠实度锚点句 Top-{r.fidelity_anchors.length}（与原文相似度排序）
                    </Space>
                  ),
                  children: (
                    <Table
                      dataSource={r.fidelity_anchors.map((a: FidelityAnchor, i: number) => ({
                        key: i,
                        sentence: a.sentence,
                        sim: a.sim,
                      }))}
                      rowKey="key"
                      pagination={false}
                      size="small"
                      columns={[
                        {
                          title: "报告句子",
                          dataIndex: "sentence",
                          ellipsis: true,
                        },
                        {
                          title: "相似度",
                          dataIndex: "sim",
                          width: 90,
                          render: (v: number) => {
                            const pct = Math.round(v * 100);
                            return (
                              <Tag color={v >= 0.6 ? "green" : v >= 0.35 ? "gold" : "red"}>
                                {pct}%
                              </Tag>
                            );
                          },
                        },
                      ]}
                    />
                  ),
                },
              ]}
            />
          )}

          {/* 疑似编造句（fidelity_stray_claims） */}
          {r.fidelity_stray_claims && r.fidelity_stray_claims.length > 0 && (
            <Card
              title={
                <Space>
                  <TriangleAlert style={{ color: "#ff4d4f" }} />
                  疑似编造句（{r.fidelity_stray_claims.length} 条）
                </Space>
              }
              style={{ marginBottom: 16, borderColor: "#ffccc7" }}
              styles={{ header: { background: "#fff2f0" } }}
            >
              <Alert
                type="warning"
                showIcon
                message="以下句子与原论文相似度过低（< 35%）且含绝对化断言/数字，疑似编造，请逐条核实"
                style={{ marginBottom: 12 }}
              />
              {r.fidelity_stray_claims.map((s: string, i: number) => (
                <div
                  key={i}
                  style={{
                    padding: "8px 12px",
                    background: "#fff2f0",
                    borderRadius: 6,
                    marginBottom: 6,
                    borderLeft: "3px solid #ff4d4f",
                    fontSize: 13,
                  }}
                >
                  <Text style={{ color: "#cf1322" }}>{s}</Text>
                </div>
              ))}
            </Card>
          )}
          {r.claims && r.claims.length > 0 && (
            <Card title="核心观点" style={{ marginBottom: 16 }}>
              {" "}
              {r.claims.map((c: import("@/api/reflection").ReflectionClaim) => (
                <div
                  key={c.id}
                  style={{
                    padding: "10px 14px",
                    background: "var(--pf-bg-tertiary)",
                    borderRadius: 6,
                    marginBottom: 8,
                    borderLeft: "3px solid #1677ff",
                  }}
                >
                  <Space>
                    <Tag color="blue">{c.id}</Tag>
                    <span>{c.text}</span>
                    {c.evidence_id && (
                      <Tooltip title="支撑该观点的证据 ID">
                        <Tag color="green" icon={<Link />}>
                          {c.evidence_id}
                        </Tag>
                      </Tooltip>
                    )}
                  </Space>
                </div>
              ))}
            </Card>
          )}

          {r.evidence_pool && r.evidence_pool.length > 0 && (
            <Collapse
              style={{ marginBottom: 16 }}
              items={[
                {
                  key: "evidence",
                  label: (
                    <Space>
                      <FileSearch />
                      证据池 ({r.evidence_pool.length} 条原文片段)
                    </Space>
                  ),
                  children: (
                    <Table
                      dataSource={r.evidence_pool}
                      rowKey="id"
                      pagination={false}
                      size="small"
                      columns={[
                        { title: "ID", dataIndex: "id", width: 60 },
                        { title: "原文片段", dataIndex: "snippet" },
                        {
                          title: "支撑观点",
                          dataIndex: "claim_ref",
                          width: 100,
                          render: (ref: string | null) =>
                            ref ? <Tag color="blue">{ref}</Tag> : "-",
                        },
                      ]}
                    />
                  ),
                },
              ]}
            />
          )}

          {/* 总结 */}
          {r.summary && (
            <Card title="报告内容总结" style={{ marginBottom: 16 }}>
              <Paragraph style={{ whiteSpace: "pre-wrap", marginBottom: 0 }}>{r.summary}</Paragraph>
            </Card>
          )}

          {/* 元信息 */}
          <Card title="元信息" size="small">
            <Descriptions size="small" column={2}>
              <Descriptions.Item label="论文 ID">
                <Text copyable style={{ fontSize: 12 }}>
                  {result.paper_id}
                </Text>
              </Descriptions.Item>
              <Descriptions.Item label="版本">{result.version}</Descriptions.Item>
              <Descriptions.Item label="创建时间">
                {result.created_at ? new Date(result.created_at).toLocaleString() : "-"}
              </Descriptions.Item>
              <Descriptions.Item label="完成时间">
                {result.completed_at ? new Date(result.completed_at).toLocaleString() : "-"}
              </Descriptions.Item>
            </Descriptions>
          </Card>
        </>
      )}
    </div>
  );
}

import { Send, BookOpen, FileText, Inbox, XCircle, CheckCircle, Loader, Trash2 } from "lucide-react";
/**
 * ReflectionUpload 组件：弹出 Modal 让用户提交感悟/读后/复现报告。
 *
 * 支持两种提交方式（Tabs 切换）：
 * - 「粘贴文本」：单篇文本（POST /api/depth/reflection/text，JSON body）
 * - 「上传文件」：多文件批量（POST /api/depth/reflection/files，multipart）
 *   - 多文件 picker (antd Dragger multiple=true)，单次最多 20 个
 *   - 每个文件独立处理：抽取 → 去重 → 入库 → reflection 评审
 *   - 逐项返回结果，per-file 状态（pending/uploading/done/failed）
 *   - 每个 taskId 独立订阅 SSE
 *
 * 流程（多文件版）：
 * 1. 用户在文件 tab 拖拽/选择 N 个文件（PDF / DOCX / TXT / MD）
 * 2. 文件列表显示在 Dragger 下方，每项带文件名/大小/移除按钮
 * 3. 点击「批量提交」→ 走 /api/depth/reflection/files（202 + items[]）
 * 4. 对每个 accepted 的 taskId 独立订阅 SSE
 * 5. 文件列表中每项实时显示状态（pending → uploading → done/failed）
 * 6. 全部完成后关闭 modal 并调用 onSuccess 回调
 *
 * 【为什么用 Modal 而不是独立页面】
 * - 报告长度通常 500~3000 字，独立页面太重
 * - Modal 可以在 HomePage / DepthReview 报告 Tab 顶部复用
 * - 提交中状态在 modal 内展示，避免页面跳转打断上下文
 */
import { useState, useRef, useEffect } from "react";
import {
  Modal,
  Form,
  Input,
  Button,
  message,
  Space,
  Typography,
  Alert,
  Progress,
  Select,
  InputNumber,
  Tabs,
  Upload,
  Tag,
  List,
  type UploadProps,
} from "antd";

import { useTranslation } from "react-i18next";
import {
  createReflectionReport,
  uploadReflectionReports,
  type ReflectionFileBatchItem,
  type ReflectionFileBatchResponse,
  type ReflectionUploadRequest,
  type SourcePaperInfo,
} from "@/api/reflection";
import { useTaskStore } from "@/store/useTaskStore";
import { useReflectionStore } from "@/store/useReflectionStore";

const { TextArea } = Input;
const { Text } = Typography;
const { Dragger } = Upload;

interface ReflectionUploadProps {
  /** Modal 打开状态 */
  open: boolean;
  /** 关闭回调（成功或取消都触发） */
  onClose: () => void;
  /** 成功提交后回调（让父组件刷新列表 / 切换 Tab） */
  onSuccess?: (paperId: string) => void;
  /** 关联的源论文 ID（仅在「对某篇论文的读后感」场景使用） */
  sourcePaperId?: string;
  /** 关联的源论文标题（仅展示） */
  sourcePaperTitle?: string;
}

interface FormValues {
  title: string;
  content: string;
  authors: string[];
  year?: number | null;
}

interface FileFormValues {
  title: string;
  authorsCsv: string;
  year?: number | null;
}

/** 单文件在批量上传中的状态 */
type FileItemStatus = "pending" | "uploading" | "done" | "failed";
interface FileItem {
  /** 文件对象（用户选择的原始 File） */
  file: File;
  /** 唯一 key（filename + size + index 避免重复） */
  key: string;
  /** 状态 */
  status: FileItemStatus;
  /** 后端返回的 paperId（成功后填充） */
  paperId?: string;
  /** 后端返回的 taskId（订阅 SSE 用） */
  taskId?: string | null;
  /** 错误信息（失败时填充） */
  error?: string;
  /** 原论文自动识别/导入结果 */
  sourcePaper?: SourcePaperInfo | null;
}

const CURRENT_YEAR = new Date().getFullYear();
const ALLOWED_FILE_EXTS = [".pdf", ".docx", ".txt", ".md"];
const ALLOWED_FILE_TYPES = ".pdf,.docx,.txt,.md";
const MAX_FILE_SIZE_MB = 10;
/** 单次批量最多文件数（与后端 MAX_BATCH_SIZE 一致） */
const MAX_BATCH_FILES = 20;

let _fileItemKeySeq = 0;
const nextFileItemKey = () => `fi_${Date.now()}_${++_fileItemKeySeq}`;

/** 将 sourcePaper 状态渲染为用户友好的标签与提示 */
function formatSourcePaper(sp?: SourcePaperInfo | null): { color: string; text: string } | null {
  if (!sp) return null;
  const sourceLabel =
    sp.source === "semantic_scholar" ? "Semantic Scholar" : sp.source === "arxiv" ? "arXiv" : "";
  const sourceSuffix = sourceLabel ? `（${sourceLabel}）` : "";
  switch (sp.status) {
    case "imported":
      return {
        color: "green",
        text: `已自动导入《${sp.title || "未知论文"}》${sourceSuffix}`,
      };
    case "exists":
      return {
        color: "blue",
        text: `已关联库中《${sp.title || "原论文"}》${sourceSuffix}`,
      };
    case "manual":
      return { color: "blue", text: "已手动关联源论文" };
    case "no_title":
      return { color: "orange", text: "未识别到原论文题目" };
    case "rate_limited":
      return { color: "orange", text: "arXiv 限流，稍后自动重试" };
    case "no_match":
      return { color: "red", text: "未在 arXiv 找到匹配" };
    case "import_failed":
      return { color: "red", text: "原论文导入失败" };
    default:
      return null;
  }
}

export default function ReflectionUpload({
  open,
  onClose,
  onSuccess,
  sourcePaperId,
  sourcePaperTitle,
}: ReflectionUploadProps) {
  const { t } = useTranslation();
  const [textForm] = Form.useForm<FormValues>();
  const [fileForm] = Form.useForm<FileFormValues>();
  const { subscribeSSE } = useTaskStore();
  const { addUpload, updateByTaskId } = useReflectionStore();

  const [activeTab, setActiveTab] = useState<"text" | "file">("text");
  const [submitting, setSubmitting] = useState(false);
  const [progress, setProgress] = useState(0);
  const [progressMsg, setProgressMsg] = useState("");
  const [error, setError] = useState<string | null>(null);
  // 多文件列表（替代单文件版的 pickedFile）
  const [fileItems, setFileItems] = useState<FileItem[]>([]);
  const unsubscribeRef = useRef<(() => void) | null>(null);
  // 【修复 SSE 泄漏】批量模式下每个文件订阅一个 SSE，需要逐个清理。
  // 文本模式只用 unsubscribeRef（保留单 ref 避免不必要改动）。
  const batchUnsubsRef = useRef<Set<() => void>>(new Set());
  // 【修复 onSuccess 重复】记录批量提交时的总文件数，仅在最后一个文件完成时
  // 触发一次 onSuccess（避免 20-file 批量触发 20 次父组件列表刷新）。
  const batchTotalRef = useRef<number>(0);
  // 文件上传完成后置 true，防卫 axios onUploadProgress 在 promise resolve 后
  // 仍然偶然跳出事件（如 keep-alive / HTTP/2 场景）导致进度条倒退。
  const uploadDoneRef = useRef<boolean>(false);

  // Modal 关闭时清理 SSE 订阅 + 重置表单
  useEffect(() => {
    if (!open) {
      unsubscribeRef.current?.();
      unsubscribeRef.current = null;
      // 清理所有批量模式 SSE 订阅（避免 EventSource 连接泄漏）
      batchUnsubsRef.current.forEach((u) => u());
      batchUnsubsRef.current.clear();
      batchTotalRef.current = 0;
      setProgress(0);
      setProgressMsg("");
      setError(null);
      setSubmitting(false);
      setFileItems([]);
      setActiveTab("text");
      textForm.resetFields();
      fileForm.resetFields();
    }
    return () => {
      unsubscribeRef.current?.();
      unsubscribeRef.current = null;
      batchUnsubsRef.current.forEach((u) => u());
      batchUnsubsRef.current.clear();
    };
  }, [open, textForm, fileForm]);

  /** 文本模式：单报告完成回调 */
  const handleTaskComplete = (paperId: string, taskId: string | null) => {
    setProgress(100);
    setProgressMsg("评审完成");
    if (taskId) updateByTaskId(taskId, "completed");
    message.success("报告评审完成");
    setTimeout(() => {
      onSuccess?.(paperId);
      onClose();
    }, 800);
  };

  const handleTaskFail = (taskId: string | null, errMsg: string) => {
    setError(errMsg);
    if (taskId) updateByTaskId(taskId, "failed", errMsg);
    setSubmitting(false);
  };

  /** 订阅单 task 的 SSE 进度 */
  const subscribeToTask = (taskId: string, paperId: string) => {
    setProgress((prev) => Math.max(prev, 10));
    setProgressMsg("已提交，等待评审...");
    const unsub = subscribeSSE(
      taskId,
      (info) => {
        setProgress((prev) => Math.max(prev, info.progress));
        setProgressMsg(info.progressMessage || "评审中...");
        updateByTaskId(taskId, info.status);
      },
      () => handleTaskComplete(paperId, taskId),
      (info) => handleTaskFail(taskId, info.error || "评审失败"),
    );
    unsubscribeRef.current = unsub;
  };

  // 文本模式提交
  const handleTextSubmit = async (values: FormValues) => {
    setError(null);
    setSubmitting(true);
    setProgress(5);
    setProgressMsg("提交中...");

    const payload: ReflectionUploadRequest = {
      title: values.title.trim(),
      content: values.content.trim(),
      authors: values.authors,
      year: values.year,
      sourcePaperId: sourcePaperId ?? null,
    };

    try {
      const resp = await createReflectionReport(payload);
      addUpload(resp.paperId, values.title, resp.taskId);
      message.success(`已提交（task_id=${resp.taskId ?? "pending"}）`);
      if (resp.taskId) {
        subscribeToTask(resp.taskId, resp.paperId);
      } else {
        // 后端未返回 taskId（理论上不会发生）—— 直接关闭
        handleTaskComplete(resp.paperId, null);
      }
    } catch (e: any) {
      const errMsg = e?.response?.data?.detail || e?.message || "提交失败";
      handleTaskFail(null, errMsg);
      setProgress(0);
    }
  };

  /**
   * 多文件模式提交：
   * 1. 设置所有文件状态为 uploading
   * 2. POST /api/depth/reflection/files（含全部 files）
   * 3. 根据 response.items 逐项更新状态
   * 4. 对 accepted 的 taskId 独立订阅 SSE
   * 5. 聚合进度：成功数 / 总数
   */
  const handleBatchFileSubmit = async (values: FileFormValues) => {
    if (fileItems.length === 0) {
      setError(t("reflection.upload.fileRequired", "请先选择要上传的文件"));
      return;
    }
    // 二次校验：单文件大小（前端先过滤一次，后端再校验）
    const oversize = fileItems.filter((it) => it.file.size > MAX_FILE_SIZE_MB * 1024 * 1024);
    if (oversize.length > 0) {
      setError(
        t(
          "reflection.upload.fileTooLarge",
          `${oversize.length} 个文件超过 ${MAX_FILE_SIZE_MB}MB 上限：${oversize
            .map((it) => it.file.name)
            .join(", ")}`,
        ),
      );
      return;
    }

    setError(null);
    setSubmitting(true);
    setProgress(0);
    setProgressMsg("准备上传...");
    uploadDoneRef.current = false;

    // 全部标记为 uploading
    setFileItems((prev) => prev.map((it) => ({ ...it, status: "uploading" as FileItemStatus })));

    const meta = {
      title: values.title?.trim() || undefined,
      authorsCsv: values.authorsCsv?.trim() || undefined,
      year: values.year || undefined,
      sourcePaperId: sourcePaperId || undefined,
    };
    const files = fileItems.map((it) => it.file);
    try {
      const resp: ReflectionFileBatchResponse = await uploadReflectionReports(
        files,
        meta,
        (percent) => {
          if (uploadDoneRef.current) return;
          // 上传阶段只走到 50%，剩余留给 SSE
          setProgress(Math.min(percent / 2, 50));
          setProgressMsg(`上传中 ${percent}%...（${fileItems.length} 个文件）`);
        },
      );
      uploadDoneRef.current = true;
      // 后端开始处理：固定在 50% 等待 SSE 接管
      setProgress(50);
      setProgressMsg(`已提交 ${resp.items.length} 个文件，等待评审...`);

      // 记录本次批量提交的总文件数（用于 onSuccess 防抖）
      const acceptedCount = resp.items.filter((it) => it.status === "accepted" && it.taskId).length;
      batchTotalRef.current = acceptedCount;

      // 根据后端返回的 items 逐项更新状态 + 订阅 SSE
      const byFilename: Record<string, ReflectionFileBatchItem> = {};
      for (const it of resp.items) byFilename[it.filename] = it;
      setFileItems((prev) =>
        prev.map((local) => {
          const remote = byFilename[local.file.name];
          if (!remote) return local;
          if (remote.status === "accepted" && remote.taskId) {
            addUpload(remote.paperId || "", local.file.name, remote.taskId);
            // 订阅 SSE
            subscribeToTaskPerFile(remote.taskId, remote.paperId || "", local.key);
            return {
              ...local,
              // 保持 uploading 状态；SSE 完成回调会翻转为 done/failed。
              // 之前误设为 'done' 会让文件在评审完成前就显示绿色勾（30s 误判）。
              status: "uploading",
              paperId: remote.paperId || undefined,
              taskId: remote.taskId,
              sourcePaper: remote.sourcePaper,
            };
          }
          if (remote.status === "failed") {
            return { ...local, status: "failed", error: remote.error };
          }
          return local;
        }),
      );
      message.success(
        resp.failed > 0
          ? `已处理 ${resp.total} 个文件：${resp.submitted} 成功 / ${resp.failed} 失败`
          : `已提交 ${resp.submitted} 份报告`,
      );
    } catch (e: any) {
      uploadDoneRef.current = true;
      const errMsg = e?.response?.data?.detail || e?.message || "上传失败";
      handleTaskFail(null, errMsg);
      setFileItems((prev) =>
        prev.map((it) =>
          it.status === "uploading" ? { ...it, status: "failed", error: errMsg } : it,
        ),
      );
      setProgress(0);
    }
  };

  /**
   * 单文件 SSE 订阅（不更新顶层 progress —— 多文件版进度由聚合统计驱动）
   * 通过闭包持有 fileKey 用于更新该文件的最终状态
   *
   * 【修复 SSE 泄漏】将 unsubscribe 函数存入 batchUnsubsRef，
   * modal 关闭时统一清理，避免 EventSource 连接泄漏。
   */
  const subscribeToTaskPerFile = (taskId: string, paperId: string, fileKey: string) => {
    const unsub = subscribeSSE(
      taskId,
      (_info) => {
        // 不更新顶层 progress，由聚合统计驱动
        updateByTaskId(taskId, _info.status);
      },
      () => {
        // completed
        setFileItems((prev) =>
          prev.map((it) => (it.key === fileKey ? { ...it, status: "done" } : it)),
        );
        // 仅在最后一个 accepted 文件完成时触发一次 onSuccess
        // （失败的文件不计入，避免因某个失败一直卡住不回调）
        batchTotalRef.current = Math.max(0, batchTotalRef.current - 1);
        if (batchTotalRef.current === 0 && paperId) {
          onSuccess?.(paperId);
        }
      },
      (info) => {
        // failed
        setFileItems((prev) =>
          prev.map((it) =>
            it.key === fileKey ? { ...it, status: "failed", error: info.error || "评审失败" } : it,
          ),
        );
        // 失败也递减，避免 accepted 全完成但某文件卡 running 时 onSuccess 永不触发
        batchTotalRef.current = Math.max(0, batchTotalRef.current - 1);
      },
    );
    batchUnsubsRef.current.add(unsub);
  };

  /**
   * 聚合进度 = 已完成 (done) 数量 / 总数 × 100
   * 用于驱动顶层 Progress 条
   */
  const aggregateProgress =
    fileItems.length === 0
      ? 0
      : Math.round(
          (fileItems.filter((it) => it.status === "done" || it.status === "failed").length /
            fileItems.length) *
            100,
        );
  const completedCount = fileItems.filter((it) => it.status === "done").length;
  const failedCount = fileItems.filter((it) => it.status === "failed").length;

  /**
   * 切换 tab 时清空 file 模式选择的文件
   */
  const handleTabChange = (k: string) => {
    if (submitting) return;
    const next = k as "text" | "file";
    if (next !== activeTab) {
      setFileItems([]);
      fileForm.resetFields();
    }
    setActiveTab(next);
  };

  /** 移除单个文件（提交前） */
  const removeFileItem = (key: string) => {
    if (submitting) return;
    setFileItems((prev) => prev.filter((it) => it.key !== key));
  };

  /** 清空所有文件 */
  const clearAllFileItems = () => {
    if (submitting) return;
    setFileItems([]);
  };

  // Dragger beforeUpload：累积多文件到 fileItems
  const draggerProps: UploadProps = {
    multiple: true,
    showUploadList: false,
    accept: ALLOWED_FILE_TYPES,
    beforeUpload: (file) => {
      // antd 在多选模式下 beforeUpload 会被每个文件分别调用；fileList 是当前批次的全部文件
      const ext = "." + (file.name.split(".").pop() || "").toLowerCase();
      if (!ALLOWED_FILE_EXTS.includes(ext)) {
        message.error(
          t("reflection.upload.fileTypeError", `不支持的文件类型 ${ext}：${file.name}`),
        );
        return Upload.LIST_IGNORE;
      }
      if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
        message.error(
          t("reflection.upload.fileTooLarge", `文件超过 ${MAX_FILE_SIZE_MB}MB：${file.name}`),
        );
        return Upload.LIST_IGNORE;
      }
      // 累积到 fileItems（去重：filename + size 相同的不重复添加）
      setFileItems((prev) => {
        if (prev.some((it) => it.file.name === file.name && it.file.size === file.size)) {
          return prev;
        }
        return [
          ...prev,
          {
            file,
            key: nextFileItemKey(),
            status: "pending",
          },
        ];
      });
      // 自动用第一个文件名（去扩展名）作为默认标题候选
      if (!fileForm.getFieldValue("title")) {
        const stem = file.name.replace(/\.[^.]+$/, "");
        fileForm.setFieldValue("title", stem);
      }
      return false; // 阻止 antd 默认上传
    },
  };

  return (
    <Modal
      title={
        <Space>
          <BookOpen style={{ color: "var(--pf-primary)" }} />
          {t("reflection.upload.title", "提交感悟报告")}
        </Space>
      }
      open={open}
      onCancel={onClose}
      footer={null}
      width={680}
      destroyOnHidden
      maskClosable={!submitting}
      closable={!submitting}
    >
      {error && (
        <Alert
          type="error"
          message={error}
          showIcon
          closable
          onClose={() => setError(null)}
          style={{ marginBottom: 16 }}
        />
      )}

      {submitting && (
        <div style={{ marginBottom: 16 }}>
          <Progress
            percent={Math.max(progress, aggregateProgress)}
            status={progress >= 100 || aggregateProgress >= 100 ? "success" : "active"}
            strokeColor="#6366f1"
          />
          <Text type="secondary" style={{ fontSize: 12 }}>
            {progressMsg}
            {fileItems.length > 1 &&
              `（${completedCount}/${fileItems.length} 完成，${failedCount} 失败）`}
          </Text>
        </div>
      )}

      {sourcePaperId && (
        <Alert
          type="info"
          showIcon
          style={{ marginBottom: 16 }}
          message={
            <span>
              关联论文：<Text strong>{sourcePaperTitle || sourcePaperId}</Text>
            </span>
          }
        />
      )}

      <Tabs
        activeKey={activeTab}
        onChange={handleTabChange}
        items={[
          {
            key: "text",
            label: (
              <span>
                <FileText /> {t("reflection.upload.tabText", "粘贴文本")}
              </span>
            ),
            children: (
              <Form
                form={textForm}
                layout="vertical"
                onFinish={handleTextSubmit}
                disabled={submitting}
                initialValues={{ authors: [], year: CURRENT_YEAR }}
              >
                <Form.Item
                  label="报告标题"
                  name="title"
                  rules={[
                    { required: true, message: "请输入报告标题" },
                    { max: 200, message: "标题不能超过 200 字" },
                  ]}
                >
                  <Input placeholder="如：读《Attention Is All You Need》有感" />
                </Form.Item>

                <Form.Item label="作者（可选）" name="authors" tooltip="回车添加多个作者">
                  <Select
                    mode="tags"
                    placeholder="输入作者后回车"
                    tokenSeparators={[",", "，"]}
                    maxTagCount={5}
                  />
                </Form.Item>

                <Form.Item label="年份（可选）" name="year">
                  <InputNumber
                    min={1900}
                    max={CURRENT_YEAR + 1}
                    placeholder={String(CURRENT_YEAR)}
                    style={{ width: 120 }}
                  />
                </Form.Item>

                <Form.Item
                  label="报告内容"
                  name="content"
                  rules={[
                    { required: true, message: "请输入报告内容" },
                    { min: 50, message: "内容至少 50 字（评审需要充分证据）" },
                  ]}
                  extra="建议至少 200 字，包含具体观点、引用、和自己的思考。LLM 将从中提取证据并打分。"
                >
                  <TextArea
                    rows={10}
                    placeholder={
                      "请撰写你的感悟/读后/复现报告。建议结构：\n" +
                      "1. 简述原论文的核心方法\n" +
                      "2. 你的理解与思考（理解准确性）\n" +
                      "3. 对细节的深入分析（分析深度）\n" +
                      "4. 你的创新观点或批判（创新性见解）\n" +
                      "5. 引用支撑（观点必须有逻辑或引用支撑）"
                    }
                    showCount
                    maxLength={20000}
                  />
                </Form.Item>

                <Form.Item style={{ marginBottom: 0, textAlign: "right" }}>
                  <Space>
                    <Button onClick={onClose} disabled={submitting}>
                      取消
                    </Button>
                    <Button
                      type="primary"
                      htmlType="submit"
                      icon={<Send />}
                      loading={submitting}
                    >
                      {submitting ? "评审中..." : "提交评审"}
                    </Button>
                  </Space>
                </Form.Item>
              </Form>
            ),
          },
          {
            key: "file",
            label: (
              <span>
                <Inbox /> {t("reflection.upload.tabFile", "上传文件")}
                {fileItems.length > 0 && (
                  <Tag color="blue" style={{ marginLeft: 6 }}>
                    {fileItems.length}
                  </Tag>
                )}
              </span>
            ),
            children: (
              <Form
                form={fileForm}
                layout="vertical"
                onFinish={handleBatchFileSubmit}
                disabled={submitting}
                initialValues={{ title: "", authorsCsv: "", year: CURRENT_YEAR }}
              >
                <Form.Item>
                  <Dragger {...draggerProps} style={{ padding: "8px 0" }}>
                    <p className="ant-upload-drag-icon">
                      <Inbox style={{ color: "#6366f1" }} />
                    </p>
                    <p className="ant-upload-text">
                      {t(
                        "reflection.upload.fileDropHint",
                        `点击或拖拽文件到此区域上传（支持 PDF / DOCX / TXT / MD，单次最多 ${MAX_BATCH_FILES} 个，每个最大 ${MAX_FILE_SIZE_MB}MB）`,
                      )}
                    </p>
                    <p className="ant-upload-hint" style={{ fontSize: 12 }}>
                      {t(
                        "reflection.upload.fileTypes",
                        "后端会按扩展名分发抽取：PDF → pypdf，DOCX → python-docx，TXT/MD → UTF-8 文本",
                      )}
                    </p>
                  </Dragger>
                </Form.Item>

                {fileItems.length > 0 && (
                  <div style={{ marginBottom: 16 }}>
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        marginBottom: 8,
                      }}
                    >
                      <Text strong>已选择 {fileItems.length} 个文件：</Text>
                      {!submitting && fileItems.length > 1 && (
                        <Button
                          size="small"
                          type="text"
                          icon={<Trash2 />}
                          onClick={clearAllFileItems}
                        >
                          清空
                        </Button>
                      )}
                    </div>
                    <List
                      size="small"
                      bordered
                      dataSource={fileItems}
                      renderItem={(it) => (
                        <List.Item
                          actions={
                            !submitting && it.status === "pending"
                              ? [
                                  <Button
                                    key="del"
                                    type="text"
                                    size="small"
                                    icon={<Trash2 />}
                                    onClick={() => removeFileItem(it.key)}
                                  />,
                                ]
                              : undefined
                          }
                        >
                          <Space>
                            {it.status === "pending" && <FileText />}
                            {it.status === "uploading" && (
                              <Loader style={{ color: "#6366f1" }} />
                            )}
                            {it.status === "done" && (
                              <CheckCircle style={{ color: "#52c41a" }} />
                            )}
                            {it.status === "failed" && (
                              <XCircle style={{ color: "#ff4d4f" }} />
                            )}
                            <Text style={{ maxWidth: 280 }} ellipsis>
                              {it.file.name}
                            </Text>
                            <Text type="secondary" style={{ fontSize: 12 }}>
                              ({(it.file.size / 1024).toFixed(1)} KB)
                            </Text>
                            {(() => {
                              const spLabel = formatSourcePaper(it.sourcePaper);
                              return spLabel ? (
                                <Tag color={spLabel.color} style={{ fontSize: 12 }}>
                                  {spLabel.text}
                                </Tag>
                              ) : null;
                            })()}
                            {it.status === "failed" && it.error && (
                              <Text type="danger" style={{ fontSize: 12 }}>
                                {it.error}
                              </Text>
                            )}
                          </Space>
                        </List.Item>
                      )}
                    />
                  </div>
                )}

                <Form.Item
                  label={t(
                    "reflection.upload.fileTitleLabel",
                    "报告标题（可选，所有文件共用；留空使用文件元数据/文件名）",
                  )}
                  name="title"
                  tooltip="如文件 PDF 内嵌标题，后端会自动抽取"
                >
                  <Input placeholder="默认使用第一个文件名（去扩展名）" />
                </Form.Item>

                <Form.Item
                  label={t(
                    "reflection.upload.fileAuthorsLabel",
                    "作者（可选，逗号分隔，所有文件共用）",
                  )}
                  name="authorsCsv"
                >
                  <Input placeholder="如：张三, 李四" />
                </Form.Item>

                <Form.Item label={t("reflection.upload.fileYearLabel", "年份（可选）")} name="year">
                  <InputNumber
                    min={1900}
                    max={CURRENT_YEAR + 1}
                    placeholder={String(CURRENT_YEAR)}
                    style={{ width: 120 }}
                  />
                </Form.Item>

                <Form.Item style={{ marginBottom: 0, textAlign: "right" }}>
                  <Space>
                    <Button onClick={onClose} disabled={submitting}>
                      取消
                    </Button>
                    <Button
                      type="primary"
                      htmlType="submit"
                      icon={<Send />}
                      loading={submitting}
                      disabled={fileItems.length === 0}
                    >
                      {submitting
                        ? `批量评审中...（${completedCount}/${fileItems.length}）`
                        : t(
                            "reflection.upload.batchFileSubmit",
                            `批量提交评审（${fileItems.length} 个）`,
                          )}
                    </Button>
                  </Space>
                </Form.Item>
              </Form>
            ),
          },
        ]}
      />
    </Modal>
  );
}

import {
  Library,
  FileText,
  UploadCloud,
  Brain,
  SlidersHorizontal,
  Scale,
  Trophy,
  Eye,
  Antenna,
  Tag,
  Package,
  X,
  BookOpen,
  type LucideIcon,
} from "lucide-react";
import { useTranslation } from "react-i18next";
import { usePaperStore } from "@/store/usePaperStore";

export interface SideBarProps {
  /** 移动端抽屉是否展开 */
  mobileOpen?: boolean;
  /** 移动端关闭抽屉（点击条目 / 遮罩 / 关闭按钮时触发） */
  onClose?: () => void;
}

// 分类 key → Lucide 图标映射（统一线性风格，stroke=currentColor 由 CSS 控色）
const CATEGORY_ICON: Record<string, LucideIcon> = {
  all: Library,
  arxiv: FileText,
  upload: UploadCloud,
  llm: Brain,
  lora: SlidersHorizontal,
  quant: Scale,
  ri: Trophy, // 强化学习
  rl: Trophy, // 强化学习（双映射）
  cv: Eye, // 计算机视觉
  comm: Antenna, // 通信网络
};

const FALLBACK_ICON = Tag; // 未知分类兜底
const UNCATEGORIZED_ICON = Package; // 未分类

/** 分类 key → 中文显示名对照表 */
export const CATEGORY_LABELS: Record<string, string> = {
  all: "论文",
  arxiv: "arXiv 论文",
  upload: "本地上传",
  llm: "大语言模型",
  lora: "LoRA 微调",
  quant: "模型量化",
  ri: "强化学习",
  rl: "强化学习",
  cv: "计算机视觉",
  comm: "通信网络",
};

/** 将数据库分类 key 转为中文显示名（优先查表，退化为原 formatLabel 逻辑） */
export function formatLabel(key: string): string {
  if (!key) return "";
  // 优先从对照表取中文名
  if (CATEGORY_LABELS[key]) return CATEGORY_LABELS[key];
  // 未配置映射的分类：分隔符换空格 + 每词首字母大写
  return key.replace(/[_-]+/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

interface CategoryItemProps {
  icon: LucideIcon;
  label: string;
  count: number | string;
  active: boolean;
  muted?: boolean;
  isSubItem?: boolean;
  onClick?: () => void;
}

function CategoryItem({
  icon: Icon,
  label,
  count,
  active,
  muted,
  isSubItem,
  onClick,
}: CategoryItemProps) {
  const className = `pf-category-item${active ? " pf-category-active" : ""}${
    muted ? " pf-category-item--muted" : ""
  }${isSubItem ? " pf-category-subitem" : ""}`;

  const handleClick = () => {
    if (muted) return;
    onClick?.();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (muted) return;
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      onClick?.();
    }
  };

  return (
    <div
      className={className}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      role={muted ? undefined : "button"}
      tabIndex={muted ? undefined : 0}
      aria-current={active ? "true" : undefined}
      style={muted ? { opacity: 0.6, cursor: "default" } : undefined}
    >
      <span className="pf-category-main">
        <Icon className="pf-category-icon" size={18} strokeWidth={1.75} aria-hidden="true" />
        <span className="pf-category-label">{label}</span>
      </span>
      <span className="pf-category-count">{count}</span>
    </div>
  );
}

export default function SideBar({ mobileOpen = false, onClose }: SideBarProps) {
  const { t } = useTranslation();
  const category = usePaperStore((s) => s.category);
  const setCategory = usePaperStore((s) => s.setCategory);
  const stats = usePaperStore((s) => s.stats);

  // 从 API 统计动态构建分类列表（排除空分类，按数量降序）
  const rawCategories = stats?.byCategory ?? [];

  // 感悟报告数量（从 stats 单独字段取，更稳；兜底按 byCategory 计算）
  const reportCount =
    stats?.reportCount ?? rawCategories.find((c) => c.category === "report")?.count ?? 0;

  // 有效分类（非空，且排除 'all' / 'report'，避免与静态项重复）
  const dynamicCategories = rawCategories
    .filter(
      (c) =>
        c.category && c.category.trim() !== "" && c.category !== "all" && c.category !== "report",
    )
    .sort((a, b) => b.count - a.count);

  // 未分类论文计数（category 为空/缺失的）
  const uncategorizedCount = rawCategories
    .filter((c) => !c.category || c.category.trim() === "")
    .reduce((sum, c) => sum + c.count, 0);

  const totalCount = stats?.totalPapers ?? 0;

  // 顶部标签页与侧边栏分类同步：
  // - 任何非 report 分类（含 all 与动态分类）都对应顶部「论文」标签
  // - report 分类对应顶部「感悟报告」标签
  const isPaperTabActive = category !== "report";

  // 分类高亮规则：
  // - 顶部标签指示器负责展示「论文 / 感悟报告」一级状态
  // - 下方分类列表只高亮当前选中的具体分类（all 或动态分类），
  //   避免「全部论文」与动态分类同时高亮

  const handleSelect = (cat: string) => {
    setCategory(cat);
    onClose?.(); // 移动端选择后自动收起抽屉
  };

  return (
    <>
      {/* 移动端遮罩 */}
      <div
        className={`pf-sidebar-backdrop${mobileOpen ? " is-open" : ""}`}
        onClick={onClose}
        aria-hidden={!mobileOpen}
      />

      <aside
        className={`pf-sidebar${mobileOpen ? " is-open" : ""}`}
        aria-label={t("sidebar.categories")}
      >
        <div className="pf-sidebar-header">
          <span className="pf-sidebar-title">{t("sidebar.categories")}</span>
          <button
            type="button"
            className="pf-sidebar-close"
            onClick={onClose}
            aria-label={t("sidebar.close", "关闭导航")}
          >
            <X size={18} />
          </button>
        </div>

        {/* 顶部「论文 / 感悟报告」标签页指示器：与 HomePage 顶部标签同步，
            将一级内容切换与具体分类高亮分离，避免两个项目同时高亮 */}
        <div className="pf-sidebar-tabs">
          <button
            type="button"
            className={`pf-sidebar-tab${isPaperTabActive ? " active" : ""}`}
            onClick={() => handleSelect("all")}
            aria-pressed={isPaperTabActive}
          >
            {t("home.tabs.papers", "论文")}
          </button>
          <button
            type="button"
            className={`pf-sidebar-tab${!isPaperTabActive ? " active" : ""}`}
            onClick={() => handleSelect("report")}
            aria-pressed={!isPaperTabActive}
          >
            {t("home.tabs.reports", "感悟报告")}
          </button>
        </div>

        <nav className="pf-category-list" aria-label={t("sidebar.categories")}>
          {/* 论文（静态首项，与顶部「论文」标签镜像）——仅当 category === "all" 时高亮 */}
          <CategoryItem
            icon={Library}
            label={CATEGORY_LABELS.all}
            count={totalCount}
            active={category === "all"}
            onClick={() => handleSelect("all")}
          />

          {/* 动态分类（作为「论文」的子项展示） */}
          {dynamicCategories.map((c) => (
            <CategoryItem
              key={c.category}
              icon={CATEGORY_ICON[c.category] ?? FALLBACK_ICON}
              label={formatLabel(c.category)}
              count={c.count}
              active={category === c.category}
              isSubItem
              onClick={() => handleSelect(c.category)}
            />
          ))}

          {/* 感悟报告（单独入口，与论文列表分离） */}
          <CategoryItem
            icon={BookOpen}
            label={t("sidebar.reflectionReports")}
            count={reportCount}
            active={category === "report"}
            onClick={() => handleSelect("report")}
          />

          {/* 未分类论文（仅当存在时显示，不可点击筛选，仅展示计数） */}
          {uncategorizedCount > 0 && (
            <CategoryItem
              icon={UNCATEGORIZED_ICON}
              label={t("sidebar.uncategorized")}
              count={uncategorizedCount}
              active={false}
              muted
            />
          )}
        </nav>

        <div className="pf-sidebar-footer">
          <div className="pf-sidebar-footer-title">{t("sidebar.systemStatus")}</div>
          <div className="pf-sidebar-status">
            <span className="pf-status-dot" />
            {t("sidebar.apiOnline")}
          </div>
        </div>
      </aside>
    </>
  );
}

import { Radar, RefreshCw, Zap } from "lucide-react";
import { useEffect, useRef, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { Button, Card, Spin, Table, Tag, Tooltip, message } from "antd";

import { listDepthV4Reviews, startBatchV4Review, type DepthReviewV4ListItem } from "@/api/depth";
import { useTaskStore } from "@/store/useTaskStore";
import V4ReviewProgress from "./V4ReviewProgress";
import QwenLoadingBanner from "@/components/QwenLoadingBanner";
import { useQwenStatus } from "@/hooks/useQwenStatus";
import type { TaskInfo } from "@/store/useTaskStore";

export default function V4ReviewPanel() {
  const navigate = useNavigate();

  const [v4Reviews, setV4Reviews] = useState<DepthReviewV4ListItem[]>([]);
  const [v4ReviewTotal, setV4ReviewTotal] = useState(0);
  const [v4ReviewLoading, setV4ReviewLoading] = useState(false);
  const [batchReviewLoading, setBatchReviewLoading] = useState(false);
  const [batchTask, setBatchTask] = useState<TaskInfo | null>(null);
  const unsubscribeRef = useRef<(() => void) | null>(null);
  const { subscribeSSE } = useTaskStore();
  const {
    status: qwenStatus,
    showHint,
    start: startQwenPoll,
    stop: stopQwenPoll,
  } = useQwenStatus();

  const fetchV4Reviews = useCallback(async (silent = false) => {
    if (!silent) setV4ReviewLoading(true);
    try {
      const res = await listDepthV4Reviews(5, 0);
      setV4Reviews(res.items);
      setV4ReviewTotal(res.total);
    } catch {
      // 静默降级
    } finally {
      if (!silent) setV4ReviewLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchV4Reviews();
    const timer = setInterval(() => fetchV4Reviews(true), 30_000);
    return () => {
      clearInterval(timer);
      unsubscribeRef.current?.();
    };
  }, [fetchV4Reviews]);

  const handleBatchReview = useCallback(async () => {
    setBatchReviewLoading(true);
    try {
      const res = await startBatchV4Review();
      if (res.task_id) {
        message.success(res.message);
        startQwenPoll(); // 开始轮询 Qwen 状态（冷启动/切换提示）
        const unsub = subscribeSSE(
          res.task_id,
          (info) => setBatchTask(info),
          (info) => {
            setBatchTask(info);
            setTimeout(() => setBatchTask(null), 3000);
            fetchV4Reviews();
            if (info.result) {
              const r = info.result as { succeeded?: number; failed?: number } | undefined;
              message.success(
                `批量审稿完成: ${r?.succeeded || 0} 成功${r?.failed ? `, ${r.failed} 失败` : ""}`,
              );
              stopQwenPoll(); // 任务完成 → 停止提示轮询
            }
          },
          (info) => {
            setBatchTask(info);
            setTimeout(() => setBatchTask(null), 5000);
            message.error(info.error || "批量审稿失败");
            stopQwenPoll(); // 任务失败 → 停止提示轮询
          },
        );
        unsubscribeRef.current = unsub;
      } else {
        message.info(res.message);
      }
    } catch (e: unknown) {
      const detail =
        e && typeof e === "object" && "response" in e
          ? (e as { response?: { data?: { detail?: string } } }).response?.data?.detail
          : undefined;
      message.error(detail || "批量审稿启动失败");
    } finally {
      setBatchReviewLoading(false);
    }
  }, [subscribeSSE, fetchV4Reviews]);

  const verdictColors: Record<string, string> = {
    accept: "green",
    minor_revision: "blue",
    major_revision: "orange",
    reject: "red",
  };

  const verdictLabels: Record<string, string> = {
    accept: "Accept",
    minor_revision: "Minor",
    major_revision: "Major",
    reject: "Reject",
  };

  return (
    <Card
      title={
        <span>
          <Radar style={{ color: "var(--pf-primary)", marginRight: 8 }} />
          V4.1 深度审稿记录
          <span
            style={{
              fontSize: 12,
              color: "var(--pf-text-placeholder)",
              marginLeft: 12,
              fontWeight: 400,
            }}
          >
            （共 {v4ReviewTotal} 条，按创新评分降序）
          </span>
        </span>
      }
      extra={
        <span style={{ display: "flex", gap: 8 }}>
          <Tooltip title="批量审完所有未审论文">
            <Button
              size="small"
              icon={<Zap />}
              loading={batchReviewLoading}
              onClick={handleBatchReview}
            >
              批量审稿
            </Button>
          </Tooltip>
          <Button size="small" icon={<RefreshCw />} onClick={() => fetchV4Reviews()} />
        </span>
      }
      style={{ marginBottom: 20 }}
    >
      <Spin spinning={v4ReviewLoading}>
        {showHint && <QwenLoadingBanner status={qwenStatus} />}
        <V4ReviewProgress task={batchTask} />
        {v4Reviews.length === 0 ? (
          <div
            style={{
              textAlign: "center",
              padding: "24px 0",
              color: "var(--pf-text-placeholder)",
            }}
          >
            暂无审稿记录，上传论文后将自动触发审稿，或点击「批量审稿」审完论文库。
          </div>
        ) : (
          <Table
            dataSource={v4Reviews}
            rowKey="id"
            size="small"
            pagination={false}
            columns={[
              { title: "论文", dataIndex: "paper_title", ellipsis: true },
              {
                title: "创新分",
                dataIndex: "novelty_score",
                width: 80,
                render: (s: number | null) =>
                  s != null ? (
                    <span
                      style={{
                        fontWeight: 700,
                        color: s >= 0.7 ? "#52c41a" : s >= 0.5 ? "#faad14" : "#ff4d4f",
                      }}
                    >
                      {(s * 100).toFixed(0)}%
                    </span>
                  ) : (
                    "-"
                  ),
              },
              {
                title: "热点契合",
                dataIndex: "hotspot_alignment_score",
                width: 90,
                render: (s: number | null) => (s != null ? `${(s * 100).toFixed(0)}%` : "-"),
              },
              {
                title: "核心贡献",
                dataIndex: "core_contribution",
                ellipsis: true,
                width: 200,
                render: (c: string | null) => c || "-",
              },
              {
                title: "裁决",
                dataIndex: "final_verdict",
                width: 100,
                render: (v: string | null) => {
                  if (!v) return "-";
                  return <Tag color={verdictColors[v] || "default"}>{verdictLabels[v] || v}</Tag>;
                },
              },
              {
                title: "时间",
                dataIndex: "completed_at",
                width: 150,
                render: (t: string | null) => (t ? new Date(t).toLocaleString() : "-"),
              },
            ]}
            onRow={(record) => ({
              onClick: () => navigate(`/depth-v4/result/${record.paper_id}?highlight=1`),
              style: { cursor: "pointer" },
            })}
          />
        )}
      </Spin>
    </Card>
  );
}

