import { ArrowLeft, Download, Table as TableIcon } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { Button, Card, Empty, Input, Select, Space, Spin, Table, Typography, message } from "antd";

import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { fetchComparePapers, fetchPapers } from "@/api/papers";
import type { ComparisonRow } from "@/api/types";

const { TextArea } = Input;

interface PaperOption {
  label: string;
  value: string;
}

export default function ComparePapersPage() {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [question, setQuestion] = useState("");
  const [loading, setLoading] = useState(false);
  const [rows, setRows] = useState<ComparisonRow[]>([]);
  const [generatedAt, setGeneratedAt] = useState<string>("");
  const [modelUsed, setModelUsed] = useState<string>("");
  const [paperOptions, setPaperOptions] = useState<PaperOption[]>([]);
  const [optionsLoading, setOptionsLoading] = useState(false);
  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    loadOptions("");
    return () => {
      if (searchTimer.current) clearTimeout(searchTimer.current);
    };
  }, []);

  const loadOptions = async (keyword: string) => {
    setOptionsLoading(true);
    try {
      const result = await fetchPapers({ keyword, pageSize: 50 });
      setPaperOptions(
        result.items.map((p) => ({
          label: `${p.title} (${p.year || "N/A"})`,
          value: p.id,
        })),
      );
    } catch {
      message.error(t("compare.loadError"));
    } finally {
      setOptionsLoading(false);
    }
  };

  const handleSearch = (value: string) => {
    if (searchTimer.current) clearTimeout(searchTimer.current);
    searchTimer.current = setTimeout(() => {
      loadOptions(value);
    }, 300);
  };

  const handleCompare = async () => {
    if (selectedIds.length < 2) {
      message.warning(t("compare.selectAtLeastTwo"));
      return;
    }
    setLoading(true);
    setRows([]);
    try {
      const res = await fetchComparePapers({
        paper_ids: selectedIds,
        question: question.trim() || undefined,
      });
      const returnedIds = new Set(res.rows.map((r) => r.paper_id));
      const missing = selectedIds.filter((id) => !returnedIds.has(id));
      if (missing.length > 0) {
        message.warning(t("compare.partialResult", { count: missing.length }));
      }
      setRows(res.rows);
      setGeneratedAt(res.generated_at);
      setModelUsed(res.model);
    } catch (err: any) {
      message.error(err?.message || t("compare.compareError"));
    } finally {
      setLoading(false);
    }
  };

  const escapeMd = (text: string) =>
    String(text || "-")
      .replace(/\|/g, "\\|")
      .replace(/\n/g, " ");

  const handleExportMarkdown = () => {
    if (!rows.length) return;
    const lines: string[] = [];
    lines.push("# " + t("compare.title"));
    lines.push("");
    lines.push(
      "| " +
        t("compare.fieldTitle") +
        " | " +
        rows.map((r) => escapeMd(r.title)).join(" | ") +
        " |",
    );
    lines.push("| " + rows.map(() => "---").join(" | ") + " |");
    const fields: { key: keyof ComparisonRow; label: string }[] = [
      { key: "authors", label: t("compare.fieldAuthors") },
      { key: "year", label: t("compare.fieldYear") },
      { key: "method", label: t("compare.fieldMethod") },
      { key: "sample_size", label: t("compare.fieldSampleSize") },
      { key: "main_results", label: t("compare.fieldMainResults") },
      { key: "metrics", label: t("compare.fieldMetrics") },
      { key: "limitations", label: t("compare.fieldLimitations") },
      { key: "conclusion", label: t("compare.fieldConclusion") },
    ];
    for (const { key, label } of fields) {
      const values = rows.map((r) => {
        const raw = r[key];
        let text: string;
        if (Array.isArray(raw)) {
          text = raw.join(", ") || "-";
        } else {
          text = String(raw || "-");
        }
        return escapeMd(text);
      });
      lines.push(`| ${label} | ${values.join(" | ")} |`);
    }
    lines.push("");
    if (generatedAt) {
      lines.push(`*${t("compare.generatedAt")}: ${generatedAt}*`);
    }
    const blob = new Blob([lines.join("\n")], { type: "text/markdown" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "comparison.md";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    message.success(t("compare.exportedMarkdown"));
  };

  const columns = useMemo(() => {
    const base = [
      {
        title: t("compare.fieldTitle"),
        dataIndex: "title",
        key: "title",
        width: 220,
        fixed: "left" as const,
        render: (text: string, record: ComparisonRow) => (
          <Typography.Link onClick={() => navigate(`/paper/${record.paper_id}`)}>
            {text}
          </Typography.Link>
        ),
      },
      {
        title: t("compare.fieldAuthors"),
        dataIndex: "authors",
        key: "authors",
        width: 160,
        render: (authors: string[]) => (authors || []).join(", ") || "-",
      },
      {
        title: t("compare.fieldYear"),
        dataIndex: "year",
        key: "year",
        width: 90,
        sorter: (a: ComparisonRow, b: ComparisonRow) => (a.year || 0) - (b.year || 0),
      },
      {
        title: t("compare.fieldMethod"),
        dataIndex: "method",
        key: "method",
        width: 220,
        filters: Array.from(new Set(rows.map((r) => r.method).filter(Boolean))).map((v) => ({
          text: v,
          value: v,
        })),
        onFilter: (value: React.Key | boolean, record: ComparisonRow) =>
          (record.method || "").includes(value as string),
      },
      {
        title: t("compare.fieldSampleSize"),
        dataIndex: "sample_size",
        key: "sample_size",
        width: 180,
      },
      {
        title: t("compare.fieldMainResults"),
        dataIndex: "main_results",
        key: "main_results",
        width: 260,
      },
      {
        title: t("compare.fieldMetrics"),
        dataIndex: "metrics",
        key: "metrics",
        width: 160,
        filters: Array.from(new Set(rows.map((r) => r.metrics).filter(Boolean))).map((v) => ({
          text: v,
          value: v,
        })),
        onFilter: (value: React.Key | boolean, record: ComparisonRow) =>
          (record.metrics || "").includes(value as string),
      },
      {
        title: t("compare.fieldLimitations"),
        dataIndex: "limitations",
        key: "limitations",
        width: 220,
      },
      {
        title: t("compare.fieldConclusion"),
        dataIndex: "conclusion",
        key: "conclusion",
        width: 240,
        filters: Array.from(new Set(rows.map((r) => r.conclusion).filter(Boolean))).map((v) => ({
          text: v,
          value: v,
        })),
        onFilter: (value: React.Key | boolean, record: ComparisonRow) =>
          (record.conclusion || "").includes(value as string),
      },
    ];
    return base;
  }, [t, navigate, rows]);

  return (
    <div style={{ maxWidth: 1400, margin: "0 auto" }}>
      <div style={{ marginBottom: 20, display: "flex", alignItems: "center", gap: 12 }}>
        <Button icon={<ArrowLeft />} onClick={() => navigate(-1)}>
          {t("common.back")}
        </Button>
        <Typography.Title level={3} className="pf-page-title" style={{ marginBottom: 0 }}>
          {t("compare.title")}
        </Typography.Title>
      </div>

      <Typography.Paragraph type="secondary" style={{ marginBottom: 20 }}>
        {t("compare.subtitle")}
      </Typography.Paragraph>

      <Card className="pf-glass-card" variant="borderless" style={{ marginBottom: 20 }}>
        <Space direction="vertical" style={{ width: "100%" }} size="large">
          <div>
            <Typography.Text strong>{t("compare.selectPapers")}</Typography.Text>
            <Select
              mode="multiple"
              allowClear
              showSearch
              filterOption={false}
              placeholder={t("compare.selectPlaceholder")}
              value={selectedIds}
              onChange={(value) => setSelectedIds(value.slice(0, 20))}
              onSearch={handleSearch}
              loading={optionsLoading}
              options={paperOptions}
              style={{ width: "100%", marginTop: 8 }}
              maxTagCount="responsive"
            />
          </div>

          <div>
            <Typography.Text strong>{t("compare.question")}</Typography.Text>
            <TextArea
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              placeholder={t("compare.questionPlaceholder")}
              rows={2}
              style={{ marginTop: 8 }}
            />
          </div>

          <Button
            type="primary"
            icon={<TableIcon />}
            onClick={handleCompare}
            loading={loading}
            disabled={selectedIds.length < 2}
          >
            {t("compare.startCompare")}
          </Button>
        </Space>
      </Card>

      {loading && (
        <Card
          className="pf-glass-card"
          variant="borderless"
          style={{ textAlign: "center", padding: 48 }}
        >
          <Spin size="large" />
          <div style={{ marginTop: 16, color: "var(--pf-text-muted)" }}>{t("compare.loading")}</div>
        </Card>
      )}

      {!loading && rows.length > 0 && (
        <Card
          className="pf-glass-card"
          variant="borderless"
          title={
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span>{t("compare.resultTitle")}</span>
              <Space>
                {modelUsed && (
                  <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                    {t("compare.modelUsed")}: {modelUsed}
                  </Typography.Text>
                )}
                <Button icon={<Download />} onClick={handleExportMarkdown}>
                  {t("compare.exportMarkdown")}
                </Button>
              </Space>
            </div>
          }
        >
          <Table
            dataSource={rows}
            columns={columns}
            rowKey="paper_id"
            scroll={{ x: "max-content" }}
            pagination={false}
            bordered
            size="small"
          />
        </Card>
      )}

      {!loading && rows.length === 0 && (
        <Card
          className="pf-glass-card"
          variant="borderless"
          style={{ textAlign: "center", padding: 48 }}
        >
          <Empty description={t("compare.empty")} />
        </Card>
      )}
    </div>
  );
}

import { Radar, Zap, Trophy } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { useLocation, Link } from "react-router-dom";
import {
  Alert,
  Button,
  Card,
  Empty,
  Progress,
  Space,
  Spin,
  Table,
  Tag,
  Typography,
  message,
} from "antd";

import type { DepthScore, Paper } from "@/api/types";
import { fetchPapers } from "@/api/papers";
import { pollDepthStatus, submitDepthBatch } from "@/api/depth";
import { getAuthHeaders } from "@/api/client";
import { useDepthStore } from "@/store/useDepthStore";
import DepthRadar from "@/components/DepthRadar";

const TYPE_COLORS: Record<string, string> = {
  A: "red",
  B: "blue",
  C: "green",
  D: "orange",
};

const VERDICT_COLORS: Record<string, string> = {
  accept: "green",
  minor_revision: "blue",
  major_revision: "orange",
  reject: "red",
};

export default function DepthAnalysis() {
  const { t } = useTranslation();
  const location = useLocation();
  const initialIds = useMemo(() => {
    const state = location.state as { selectedIds?: string[] } | null;
    return new Set<string>(state?.selectedIds || []);
  }, [location.state]);

  const [allPapers, setAllPapers] = useState<Paper[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(initialIds);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [total, setTotal] = useState(0);

  const { addTask, updateProgress, completeTask, failTask, failTasks, tasks } = useDepthStore();

  // 当前激活的任务（页面当前正在跟踪的任务）
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const activeTask = tasks.find((t) => t.taskId === activeTaskId);
  const evaluating = activeTask?.status === "running";
  const progress = activeTask?.progress ?? null;
  const results = activeTask?.results ?? [];
  const errors = activeTask?.errors ?? [];
  const summary = activeTask?.summary ?? null;

  // 页面加载时：检查是否有正在运行的任务，自动恢复轮询
  // 先验证后端任务仍存在，防止恢复已过期的持久化 taskId
  useEffect(() => {
    const runningTasks = tasks.filter((t) => t.status === "running");
    if (runningTasks.length === 0) return;

    const latest = runningTasks.reduce((a, b) => (a.submittedAt > b.submittedAt ? a : b));
    // 非最新的 running 任务均为上一次会话残留 → 批量标记失败（单次渲染）
    const staleItems = runningTasks
      .filter((t) => t.taskId !== latest.taskId)
      .map((t) => ({ taskId: t.taskId, errors: ["上一次会话的残留任务（服务可能已重启）"] }));
    if (staleItems.length > 0) failTasks(staleItems);

    // 验证最新任务是否仍存活
    const verifyAndResume = async () => {
      try {
        const resp = await fetch(`/api/tasks/${latest.taskId}`, {
          headers: getAuthHeaders(),
        });
        if (!resp.ok) {
          failTask(latest.taskId, ["任务已失效（服务重启或过期）"]);
          return;
        }
        const data = await resp.json();
        if (data.status === "completed" || data.status === "failed") {
          if (data.status === "completed") {
            const results = data.result?.results || [];
            // 从 results 重建 summary（不含 summary 字段时用空占位）
            const scores = results.filter((r: any) => r?.final_score != null);
            const summary = {
              total: data.result?.total || results.length,
              completed: scores.length,
              failed: results.length - scores.length,
              highest_score: scores.length ? Math.max(...scores.map((r: any) => r.final_score)) : 0,
              average_score: scores.length
                ? scores.reduce((s: number, r: any) => s + r.final_score, 0) / scores.length
                : 0,
            };
            completeTask(latest.taskId, results, summary);
          } else {
            failTask(latest.taskId, [data.error || "任务失败"]);
          }
          return;
        }
        setActiveTaskId(latest.taskId);
      } catch {
        failTask(latest.taskId, ["验证任务状态失败（网络或服务不可用）"]);
      }
    };
    verifyAndResume();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 当 activeTaskId 指向运行中任务时，恢复轮询
  useEffect(() => {
    if (!activeTaskId) return;
    const task = tasks.find((t) => t.taskId === activeTaskId);
    if (!task || task.status !== "running") return;

    const abort = new AbortController();

    const resumePolling = async () => {
      try {
        const final = await pollDepthStatus(task.taskId, (current, total) => {
          updateProgress(task.taskId, current, total);
        });
        completeTask(task.taskId, final.results || [], final.summary);
        message.success(t("depth.completed"));
      } catch (e: any) {
        if (e?.name === "AbortError") return;
        failTask(task.taskId, [e?.message || t("depth.failed")]);
        message.error(e?.message || t("depth.failed"));
      }
    };

    resumePolling();

    return () => {
      abort.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTaskId]);

  // 加载论文列表（带分页）
  const loadPapers = useCallback(
    async (p: number, ps: number) => {
      setLoading(true);
      try {
        const res = await fetchPapers({ page: p, pageSize: ps });
        setAllPapers(res.items);
        setTotal(res.total);
      } catch {
        message.error(t("depth.loadFailed"));
      } finally {
        setLoading(false);
      }
    },
    [t],
  );

  useEffect(() => {
    loadPapers(page, pageSize);
  }, [page, pageSize, loadPapers]);

  const toggleSelect = useCallback((id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const toggleSelectAll = useCallback(() => {
    const pageIds = allPapers.map((p) => p.id);
    const allSelected = pageIds.every((id) => selectedIds.has(id));
    setSelectedIds((prev) => {
      const next = new Set(prev);
      pageIds.forEach((id) => {
        if (allSelected) next.delete(id);
        else next.add(id);
      });
      return next;
    });
  }, [allPapers, selectedIds]);

  const clearSelection = useCallback(() => {
    setSelectedIds(new Set());
  }, []);

  const handleEvaluate = useCallback(async () => {
    if (selectedIds.size === 0) {
      message.warning(t("depth.selectAtLeastOne"));
      return;
    }

    try {
      const ids = Array.from(selectedIds);
      const { task_id } = await submitDepthBatch(ids);

      // 注册到持久化 store
      addTask(task_id, ids.length);
      setActiveTaskId(task_id);

      // 开始轮询
      const final = await pollDepthStatus(task_id, (current, total) => {
        updateProgress(task_id, current, total);
      });
      completeTask(task_id, final.results || [], final.summary);
      message.success(t("depth.completed"));
    } catch (e: any) {
      message.error(e?.message || t("depth.failed"));
    }
  }, [selectedIds, t, addTask, updateProgress, completeTask]);

  // 过滤掉带 error 的结果（LLM 调用失败的论文），只展示成功的结果
  const validResults = useMemo(() => {
    return results.filter((r: any) => r && !r.error && r.final_score != null);
  }, [results]);

  const ranked = useMemo(() => {
    return [...validResults].sort((a, b) => (b.final_score ?? 0) - (a.final_score ?? 0));
  }, [validResults]);

  const rowSelection = {
    selectedRowKeys: Array.from(selectedIds),
    onSelect: (record: Paper) => {
      toggleSelect(record.id);
    },
    onSelectAll: () => {
      toggleSelectAll();
    },
  };

  const paperColumns = [
    {
      title: "论文",
      dataIndex: "title",
      ellipsis: true,
      render: (text: string, record: Paper) => (
        <div>
          <div style={{ fontWeight: 500 }}>{text || "-"}</div>
          <div style={{ fontSize: 12, color: "var(--pf-text-muted)" }}>
            {(record.authors || []).slice(0, 3).join(", ")}
            {record.authors && record.authors.length > 3 ? " et al." : ""}
          </div>
        </div>
      ),
    },
    {
      title: "年份",
      dataIndex: "year",
      width: 80,
      render: (year: number) => year || "—",
    },
    {
      title: "来源",
      dataIndex: "source",
      width: 90,
      render: (source: string) => <Tag>{source || "—"}</Tag>,
    },
  ];

  const resultColumns = [
    {
      title: "#",
      width: 48,
      render: (_: any, __: DepthScore, idx: number) => <span>{idx + 1}</span>,
    },
    {
      title: t("depth.title"),
      dataIndex: "title",
      ellipsis: true,
      render: (text: string, record: DepthScore) => (
        <div>
          <div style={{ fontWeight: 500 }}>{text || "-"}</div>
          <div style={{ fontSize: 12, color: "var(--pf-text-muted)" }}>
            {record.core_contribution || ""}
          </div>
        </div>
      ),
    },
    {
      title: t("depth.type"),
      dataIndex: "type",
      width: 90,
      render: (type: string) => (
        <Tag color={TYPE_COLORS[type] || "default"}>{t(`depth.type${type}`)}</Tag>
      ),
    },
    {
      title: t("depth.finalScore"),
      dataIndex: "final_score",
      width: 110,
      sorter: (a: DepthScore, b: DepthScore) => a.final_score - b.final_score,
      render: (score: number) => {
        const s = score ?? 0;
        return (
          <span
            style={{
              fontWeight: 700,
              color: s >= 80 ? "#52c41a" : s >= 60 ? "#faad14" : "#ff4d4f",
            }}
          >
            {s.toFixed(1)}
          </span>
        );
      },
    },
    {
      title: t("depth.verdict"),
      dataIndex: "verdict",
      width: 100,
      render: (verdict: string) => (
        <Tag color={VERDICT_COLORS[verdict] || "default"}>{t(`depth.verdict_${verdict}`)}</Tag>
      ),
    },
    {
      title: t("depth.dimensions"),
      width: 280,
      render: (_: any, record: DepthScore) => (
        <Space size="small" wrap>
          <Tag>
            {t("depth.noveltyShort")} {((record.novelty_score ?? 0) * 100).toFixed(0)}
          </Tag>
          <Tag>
            {t("depth.rigorShort")} {((record.rigor_score ?? 0) * 100).toFixed(0)}
          </Tag>
          <Tag>
            {t("depth.influenceShort")} {((record.influence_score ?? 0) * 100).toFixed(0)}
          </Tag>
          <Tag>
            {t("depth.reproducibilityShort")}{" "}
            {((record.reproducibility_score ?? 0) * 100).toFixed(0)}
          </Tag>
        </Space>
      ),
    },
    {
      title: t("depth.keywords"),
      dataIndex: "keywords",
      ellipsis: true,
      render: (keywords: string[]) => (
        <Space size="small" wrap>
          {(keywords ?? []).slice(0, 5).map((k) => (
            <Tag key={k}>{k}</Tag>
          ))}
        </Space>
      ),
    },
  ];

  return (
    <div style={{ padding: 24, maxWidth: 1200, margin: "0 auto" }}>
      <Typography.Title level={4} style={{ marginTop: 0 }}>
        <Radar style={{ marginRight: 8 }} />
        {t("depth.title")}
      </Typography.Title>
      <Typography.Paragraph type="secondary" style={{ marginBottom: 16 }}>
        {t("depth.subtitle")}
      </Typography.Paragraph>

      {/* 错误结果提示 */}
      {results.length > validResults.length && (
        <Alert
          type="warning"
          message={t("depth.failedCount", { count: results.length - validResults.length })}
          style={{ marginBottom: 16 }}
          showIcon
        />
      )}

      <Card style={{ marginBottom: 16 }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginBottom: 12,
            flexWrap: "wrap",
            gap: 12,
          }}
        >
          <Space>
            <Typography.Text strong>已选择 {selectedIds.size} 篇论文</Typography.Text>
            {selectedIds.size > 0 && (
              <Button size="small" onClick={clearSelection}>
                清空选择
              </Button>
            )}
          </Space>
          <Button
            type="primary"
            icon={<Zap />}
            loading={evaluating}
            disabled={evaluating || selectedIds.size === 0}
            onClick={handleEvaluate}
          >
            {evaluating
              ? `${t("depth.evaluating")} (${progress?.current ?? 0}/${progress?.total ?? 0})`
              : t("depth.startEvaluate")}
          </Button>
        </div>

        {evaluating && progress && (
          <Progress
            percent={Math.round((progress.current / Math.max(progress.total, 1)) * 100)}
            status="active"
            style={{ marginBottom: 16 }}
          />
        )}

        <Spin spinning={loading}>
          <Table
            rowKey="id"
            dataSource={allPapers}
            columns={paperColumns}
            rowSelection={rowSelection}
            pagination={{
              current: page,
              pageSize,
              total,
              showSizeChanger: true,
              pageSizeOptions: ["10", "20", "50"],
              onChange: (p, ps) => {
                setPage(p);
                if (ps !== pageSize) {
                  setPageSize(ps);
                  setPage(1);
                }
              },
              showTotal: (t) => `共 ${t} 篇`,
            }}
            size="small"
            locale={{
              emptyText: (
                <Empty
                  description={
                    <span>
                      暂无论文。<Link to="/">返回首页</Link> 上传或导入论文。
                    </span>
                  }
                />
              ),
            }}
          />
        </Spin>
      </Card>

      {validResults.length > 0 && (
        <>
          <Card style={{ marginBottom: 16 }}>
            <div style={{ display: "flex", gap: 24, flexWrap: "wrap", alignItems: "flex-start" }}>
              <div style={{ flex: 1, minWidth: 260 }}>
                <Typography.Title level={5} style={{ marginTop: 0 }}>
                  <Trophy style={{ marginRight: 8 }} />
                  {t("depth.topPaper")}
                </Typography.Title>
                <DepthRadar score={ranked[0]} size={200} />
              </div>
              <div style={{ flex: 2, minWidth: 300 }}>
                <Typography.Title level={5} style={{ marginTop: 0 }}>
                  {t("depth.summary")}
                </Typography.Title>
                <Space size="large">
                  <div>
                    <div style={{ fontSize: 12, color: "var(--pf-text-muted)" }}>
                      {t("depth.avgScore")}
                    </div>
                    <div style={{ fontSize: 20, fontWeight: 700 }}>
                      {summary?.average_score != null
                        ? Number(summary.average_score).toFixed(1)
                        : "-"}
                    </div>
                  </div>
                  <div>
                    <div style={{ fontSize: 12, color: "var(--pf-text-muted)" }}>
                      {t("depth.maxScore")}
                    </div>
                    <div style={{ fontSize: 20, fontWeight: 700 }}>
                      {summary?.highest_score != null
                        ? Number(summary.highest_score).toFixed(1)
                        : "-"}
                    </div>
                  </div>
                  <div>
                    <div style={{ fontSize: 12, color: "var(--pf-text-muted)" }}>
                      {t("depth.completedCount")}
                    </div>
                    <div style={{ fontSize: 20, fontWeight: 700 }}>
                      {summary?.completed ?? 0}/{summary?.total ?? 0}
                    </div>
                  </div>
                </Space>
              </div>
            </div>
          </Card>

          <Card>
            <Table
              rowKey="paper_id"
              dataSource={ranked}
              columns={resultColumns}
              pagination={{ pageSize: 10 }}
              size="small"
            />
          </Card>
        </>
      )}

      {(errors ?? []).length > 0 && (
        <Card style={{ marginTop: 16 }}>
          <Typography.Text type="danger">{t("depth.errors")}</Typography.Text>
          <ul style={{ margin: "8px 0 0", paddingLeft: 18, fontSize: 12, color: "#ef4444" }}>
            {(errors ?? []).slice(0, 5).map((e, i) => (
              <li key={i}>{e}</li>
            ))}
          </ul>
        </Card>
      )}
    </div>
  );
}

import { RefreshCw, Zap, CheckCircle, XCircle, Clock, FileSearch, Trash2, SquareMinus } from "lucide-react";
/**
 * DEPTH v4.1 深度审稿页面。
 *
 * - /depth-v4/result/:paperId  审稿结果展示
 * - /depth-v4/list             审稿记录列表
 */
import { useState, useEffect, useCallback, useRef } from "react";
import { useParams, useNavigate, useSearchParams } from "react-router-dom";
import {
  Button,
  Card,
  Descriptions,
  Tag,
  Spin,
  Alert,
  Table,
  Collapse,
  Progress,
  Typography,
  Space,
  Empty,
  Tooltip,
  Tabs,
  message,
  Popconfirm,
} from "antd";

import {
  getDepthV4Result,
  listDepthV4Papers,
  startDepthV4Review,
  deleteDepthReview,
  batchDeleteDepthReviews,
  startSelectedV4Review,
  type DepthReviewV4Result,
  type DepthReviewV4PaperItem,
} from "../api/depth";
import ReflectionList from "../components/ReflectionList";
import QwenLoadingBanner from "@/components/QwenLoadingBanner";
import { useQwenStatus } from "@/hooks/useQwenStatus";

const { Title, Text, Paragraph } = Typography;

// ---- 裁决展示 ----

const VERDICT_COLORS: Record<string, string> = {
  accept: "green",
  minor_revision: "blue",
  major_revision: "orange",
  reject: "red",
};

const VERDICT_LABELS: Record<string, string> = {
  accept: "接收 Accept",
  minor_revision: "小修 Minor Revision",
  major_revision: "大修 Major Revision",
  reject: "拒稿 Reject",
};

const STATUS_ICONS: Record<string, React.ReactNode> = {
  pending: <Clock />,
  running: <RefreshCw className="pf-spin" />,
  completed: <CheckCircle />,
  failed: <XCircle />,
};

// 仅「pending/running」状态触发 409 */
const ACTIVE_STATUSES = new Set(["pending", "running"]);

// ---- 结果展示页 ----

function ScoreBar({
  label,
  score,
  color = "#1677ff",
}: {
  label: string;
  score: number;
  color?: string;
}) {
  const safeScore = Number(score ?? 0);
  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
        <Text type="secondary">{label}</Text>
        <Text strong>{(safeScore * 100).toFixed(0)}%</Text>
      </div>
      <Progress
        percent={Math.round(safeScore * 100)}
        strokeColor={color}
        showInfo={false}
        size="small"
      />
    </div>
  );
}

function DepthResultView({ paperId }: { paperId: string }) {
  const [searchParams] = useSearchParams();
  const highlighted = searchParams.get("highlight") === "1";

  const [result, setResult] = useState<DepthReviewV4Result | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const fetchingRef = useRef(false);
  const navigate = useNavigate();

  // Qwen/llama-server 加载提示轮询（冷启动/互斥切换时展示）
  const {
    status: qwenStatus,
    showHint,
    start: startQwenPoll,
    stop: stopQwenPoll,
  } = useQwenStatus();

  const fetchResult = useCallback(async () => {
    if (fetchingRef.current) return;
    fetchingRef.current = true;
    setLoading(true);
    setError(null);
    try {
      const res = await getDepthV4Result(paperId);
      setResult(res);
    } catch (e: any) {
      if (e?.response?.status === 404) {
        setError("该论文暂无审稿结果");
      } else {
        setError(e?.response?.data?.detail || "获取审稿结果失败");
      }
    } finally {
      setLoading(false);
      fetchingRef.current = false;
    }
  }, [paperId]);

  useEffect(() => {
    fetchResult();
    // 如果是 running/pending 状态，每 3 秒轮询
    const timer = setInterval(() => {
      if (result?.status === "running" || result?.status === "pending") {
        fetchResult();
      } else {
        // 审稿已结束（完成/失败）→ 停止 Qwen 状态轮询
        stopQwenPoll();
      }
    }, 3000);
    return () => clearInterval(timer);
  }, [paperId, result?.status]);

  const startReview = async () => {
    try {
      const res = await startDepthV4Review(paperId);
      message.success(`审稿任务已提交 (${res.task_id})`);
      startQwenPoll(); // 开始轮询 Qwen 状态（冷启动/切换提示）
      fetchResult();
    } catch (e: any) {
      message.error(e?.response?.data?.detail || "启动审稿失败");
    }
  };

  if (loading) return <Spin size="large" style={{ display: "block", margin: "100px auto" }} />;

  if (error && !result) {
    return (
      <div style={{ maxWidth: 700, margin: "60px auto", textAlign: "center" }}>
        <Empty description={error}>
          <Button type="primary" icon={<Zap />} onClick={startReview}>
            启动深度审稿
          </Button>
        </Empty>
      </div>
    );
  }

  if (!result) return null;

  const fv = result.final_verdict;
  const isOverridden = fv?.llm_verdict !== fv?.final_verdict;

  return (
    <div style={{ maxWidth: 900, margin: "0 auto", padding: "24px 16px" }}>
      {/* Qwen 加载/切换提示 */}
      {showHint && <QwenLoadingBanner status={qwenStatus} />}

      {/* 状态栏 */}
      <Space style={{ marginBottom: 16 }}>
        {STATUS_ICONS[result.status]}
        <Text>
          {result.status === "running"
            ? "审稿中..."
            : result.status === "completed"
              ? "审稿完成"
              : result.status === "failed"
                ? "审稿失败"
                : "等待中"}
        </Text>
        {result.status === "running" && (
          <Button size="small" icon={<RefreshCw />} onClick={fetchResult}>
            刷新
          </Button>
        )}
        {result.status !== "running" && result.status !== "pending" && (
          <Button size="small" icon={<Zap />} onClick={startReview}>
            重新审稿
          </Button>
        )}
        <Button size="small" onClick={() => navigate("/depth-v4/list")}>
          返回列表
        </Button>
      </Space>

      {result.status === "failed" && (
        <Alert
          type="error"
          message="审稿失败"
          description={result.error_message}
          style={{ marginBottom: 16 }}
          showIcon
        />
      )}

      {result.status === "running" && (
        <Alert
          type="info"
          message="审稿正在进行中，请稍候..."
          style={{ marginBottom: 16 }}
          showIcon
        />
      )}

      {result.status === "completed" && fv && (
        <>
          {/* 最终得分 + 裁决 */}
          <Card
            style={{
              marginBottom: 16,
              textAlign: "center",
              ...(highlighted
                ? {
                    animation: "pf-highlight-pulse 1.5s ease-in-out 3",
                    borderColor: "var(--pf-warning)",
                    boxShadow: "0 0 20px rgba(250, 173, 20, 0.3)",
                  }
                : {}),
            }}
          >
            <Title level={2} style={{ marginBottom: 4 }}>
              综合得分 {(Number(fv.calibrated_score ?? 0) * 100).toFixed(0)}%
            </Title>
            <Space size="middle">
              <Tag
                color={VERDICT_COLORS[fv.final_verdict] || "default"}
                style={{ fontSize: 16, padding: "4px 16px" }}
              >
                {VERDICT_LABELS[fv.final_verdict] || fv.final_verdict}
              </Tag>
              {isOverridden && (
                <Tooltip title={fv.override_reason}>
                  <Tag color="volcano">
                    硬编码覆盖 (LLM 原判: {VERDICT_LABELS[fv.llm_verdict] || fv.llm_verdict})
                  </Tag>
                </Tooltip>
              )}
            </Space>
            {isOverridden && (
              <Paragraph type="secondary" style={{ marginTop: 8, fontSize: 13 }}>
                {fv.override_reason}
              </Paragraph>
            )}
          </Card>

          {/* 各维度得分 */}
          <Card title="各维度评分" style={{ marginBottom: 16 }}>
            <ScoreBar label="创新分" score={result.q2_result?.novelty_score || 0} color="#1677ff" />
            <ScoreBar
              label="热点契合"
              score={result.q2_result?.hotspot_alignment_score || 0}
              color="#722ed1"
            />
            <ScoreBar label="严谨性" score={result.q3_result?.rigor_score || 0} color="#fa8c16" />
            <ScoreBar
              label="影响力"
              score={result.q4_result?.influence_score || 0}
              color="#52c41a"
            />
            <ScoreBar
              label="可复现性"
              score={result.q4_result?.reproducibility_score || 0}
              color="#13c2c2"
            />
            <ScoreBar label="主席校准分" score={fv.calibrated_score} color="#eb2f96" />
          </Card>

          {/* Q5a 批评 + Q5b 辩护 + Q5c 裁决理由 */}
          <Card title="辩论式校准" style={{ marginBottom: 16 }}>
            {result.q5a_result?.critique_points && result.q5a_result.critique_points.length > 0 && (
              <div style={{ marginBottom: 16 }}>
                <Text strong>🔴 质疑者 (Q5a)</Text>
                {result.q5a_result.critique_points.map((cp, i) => (
                  <Card
                    key={i}
                    size="small"
                    style={{
                      marginTop: 8,
                      borderLeft: `3px solid ${cp.severity === "fatal" ? "#ff4d4f" : "var(--pf-warning)"}`,
                    }}
                  >
                    <Space>
                      <Tag color={cp.severity === "fatal" ? "red" : "gold"}>
                        {cp.severity === "fatal" ? "致命" : "轻微"}
                      </Tag>
                      <Text>{cp.point}</Text>
                    </Space>
                  </Card>
                ))}
              </div>
            )}
            {result.q5b_result?.defense_points && result.q5b_result.defense_points.length > 0 && (
              <div style={{ marginBottom: 16 }}>
                <Text strong>🟢 辩护者 (Q5b)</Text>
                {result.q5b_result.defense_points.map((dp, i) => (
                  <Card key={i} size="small" style={{ marginTop: 8 }}>
                    <Text type="secondary">{dp}</Text>
                  </Card>
                ))}
              </div>
            )}
            {result.q5c_result?.reasoning && (
              <div>
                <Text strong>⚖️ 主席裁决 (Q5c)</Text>
                <Card size="small" style={{ marginTop: 8 }}>
                  <Text>{result.q5c_result.reasoning}</Text>
                  <br />
                  <Text type="secondary" style={{ fontSize: 12 }}>
                    Delta: {(result.q5c_result.delta ?? 0) > 0 ? "+" : ""}
                    {Number(result.q5c_result.delta ?? 0).toFixed(3)}
                    {result.q5c_result.delta_missing && " (LLM 未输出，默认 0)"}
                  </Text>
                </Card>
              </div>
            )}
          </Card>

          {/* 类型判别 */}
          <Card title="论文类型" style={{ marginBottom: 16 }}>
            <Descriptions size="small" column={2}>
              <Descriptions.Item label="主类型">{result.q1_result?.type}</Descriptions.Item>
              <Descriptions.Item label="辅类型">
                {result.q1_result?.secondary_type || "无"}
              </Descriptions.Item>
              <Descriptions.Item label="置信度">
                {(Number(result.q1_result?.confidence ?? 0) * 100).toFixed(0)}%
              </Descriptions.Item>
              <Descriptions.Item label="实质性贡献">
                {result.q0_result?.has_substance ? "是" : "否"}
              </Descriptions.Item>
            </Descriptions>
          </Card>

          {/* 证据池 */}
          {result.evidence_pool && result.evidence_pool.length > 0 && (
            <Collapse
              style={{ marginBottom: 16 }}
              items={[
                {
                  key: "evidence",
                  label: (
                    <Space>
                      <FileSearch />
                      证据池 ({result.evidence_pool.length} 条)
                    </Space>
                  ),
                  children: (
                    <Table
                      dataSource={result.evidence_pool}
                      rowKey="id"
                      pagination={false}
                      size="small"
                      columns={[
                        { title: "ID", dataIndex: "id", width: 50 },
                        { title: "内容", dataIndex: "content" },
                        { title: "章节", dataIndex: "section", width: 120 },
                        {
                          title: "关键词",
                          dataIndex: "keywords",
                          width: 180,
                          render: (k: string[]) => k?.join(", "),
                        },
                      ]}
                    />
                  ),
                },
              ]}
            />
          )}

          {/* 漏缺项 */}
          {result.q3_result?.missing_items && result.q3_result.missing_items.length > 0 && (
            <Card title="严谨性缺失项" style={{ marginBottom: 16 }}>
              {result.q3_result.missing_items.map((item, i) => (
                <Tag key={i} color="orange" style={{ marginBottom: 4 }}>
                  {item}
                </Tag>
              ))}
            </Card>
          )}
        </>
      )}
    </div>
  );
}

// ---- 列表页 ----

function DepthListPage() {
  const [data, setData] = useState<DepthReviewV4PaperItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [restartingIds, setRestartingIds] = useState<Set<string>>(new Set());
  // 跨分页持久化的勾选状态：以 paper_id 为 key（与 Table rowKey 对齐）。
  // React state 在分页切换间保留，因此用户可以跨多页累计勾选。
  // 两条批量动作都基于它：删除走 paper_ids（后端解析），重审走 paper_ids 直接。
  const [selectedPaperIds, setSelectedPaperIds] = useState<string[]>([]);
  const [batchDeleting, setBatchDeleting] = useState(false);
  const [batchReReviewing, setBatchReReviewing] = useState(false);
  const navigate = useNavigate();

  // 缓存最新 data，避免 setInterval effect 取陈旧闭包 + 避免 deps 含 data 反复重建 interval
  const dataRef = useRef(data);
  useEffect(() => {
    dataRef.current = data;
  }, [data]);

  const fetchList = useCallback(async (p: number) => {
    setLoading(true);
    try {
      const res = await listDepthV4Papers(20, (p - 1) * 20);
      setData(res.items);
      setTotal(res.total);
    } catch {
      message.error("获取审稿列表失败");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchList(page);
    // 进行中的审稿每 5 秒静默轮询，避免「重审」按钮一直停在旧状态
    const timer = setInterval(() => {
      if (dataRef.current.some((d) => ACTIVE_STATUSES.has(d.latest_status))) {
        fetchList(page);
      }
    }, 5000);
    return () => clearInterval(timer);
  }, [page, fetchList]);

  // 重新审稿：dedup-aware 后端会在 active 时返回 409
  const handleRestartReview = useCallback(
    async (paperId: string) => {
      setRestartingIds((prev) => new Set(prev).add(paperId));
      try {
        const res = await startDepthV4Review(paperId);
        message.success(`重审已提交（task_id=${res.task_id}）`);
        fetchList(page);
      } catch (e: any) {
        const status = e?.response?.status;
        const detail = e?.response?.data?.detail || e?.message || "重审启动失败";
        if (status === 409) {
          // 友好提示：单行避免 AntD static API + React 18 strict mode 问题
          const firstLine = String(detail).split("\n")[0];
          message.warning(`已有进行中的审稿任务。${firstLine}`, 4);
        } else {
          message.error(detail);
        }
        // 无论如何刷一次以拿最新状态
        fetchList(page);
      } finally {
        setRestartingIds((prev) => {
          const next = new Set(prev);
          next.delete(paperId);
          return next;
        });
      }
    },
    [page, fetchList],
  );

  const handleDelete = useCallback(
    async (recordId: string) => {
      try {
        await deleteDepthReview(recordId);
        message.success("审稿记录已删除");
        fetchList(page);
      } catch (e: any) {
        message.error(e?.response?.data?.detail || "删除失败");
      }
    },
    [page, fetchList],
  );

  // 批量删除：调用 POST /api/depth/reviews/batch-delete，传 paper_ids（后端解析）
  const handleBatchDelete = useCallback(async () => {
    if (selectedPaperIds.length === 0) return;
    setBatchDeleting(true);
    try {
      const res = await batchDeleteDepthReviews(selectedPaperIds);
      if (res.failed_ids && res.failed_ids.length > 0) {
        message.warning(
          `部分删除失败：成功 ${res.deleted_count} 条，失败 ${res.failed_ids.length} 条`,
          4,
        );
      } else {
        message.success(`已批量删除 ${res.deleted_count} 条审稿记录`);
      }
      setSelectedPaperIds([]);
      fetchList(page);
    } catch (e: any) {
      message.error(e?.response?.data?.detail || "批量删除失败");
    } finally {
      setBatchDeleting(false);
    }
  }, [selectedPaperIds, page, fetchList]);

  // 批量重新审稿：调用 POST /api/depth/v4/review-selected（复用现成的批量提交端点）
  const handleBatchReReview = useCallback(async () => {
    if (selectedPaperIds.length === 0) return;
    setBatchReReviewing(true);
    try {
      const res = await startSelectedV4Review(selectedPaperIds);
      const skipped = res.skipped || [];
      if (skipped.length === 0) {
        message.success(`已提交 ${res.submitted} 篇审稿任务，每篇独立可跟踪进度`, 3);
      } else if (res.submitted > 0) {
        // 显示前 3 条跳过原因，方便用户排查
        const sample = skipped
          .slice(0, 3)
          .map((s) => `${s.paper_id}: ${s.reason}`)
          .join(" / ");
        message.warning(
          `已提交 ${res.submitted} 篇，跳过 ${skipped.length} 篇（${sample}${skipped.length > 3 ? "…" : ""}）`,
          5,
        );
      } else {
        const sample = skipped
          .slice(0, 3)
          .map((s) => `${s.paper_id}: ${s.reason}`)
          .join(" / ");
        message.error(
          `全部跳过：${skipped.length} 篇（${sample}${skipped.length > 3 ? "…" : ""}）`,
          6,
        );
      }
      // 选中的论文可能正在审稿，清空勾选避免重复触发
      setSelectedPaperIds([]);
      fetchList(page);
    } catch (e: any) {
      message.error(e?.response?.data?.detail || "批量重审失败");
    } finally {
      setBatchReReviewing(false);
    }
  }, [selectedPaperIds, page, fetchList]);

  // Row selection：勾选以 paper_id 为 key，与 Table rowKey='paper_id' 对齐。
  // 跨分页持久化：React state 在分页切换时保留 → 勾选一组后翻页、再勾选一批，
  //           全部累积在 selectedPaperIds 中，antd Table 用受控 selectedRowKeys
  //           跨页同样能识别。
  // 禁止勾选活跃行（pending/running）：避免删除/重审时与进行中任务冲突（服务端也会兜底 409）。
  // 最大选择数保护：避免大批量提交触发后端 50/200 上限。
  const MAX_SELECTION = 50;
  const rowSelection = {
    selectedRowKeys: selectedPaperIds,
    onChange: (keys: React.Key[]) => {
      const next = keys.map(String);
      // 截断超量选择：优雅提示用户而不是静默出错
      if (next.length > MAX_SELECTION) {
        message.warning(`单次最多选择 ${MAX_SELECTION} 篇`);
        setSelectedPaperIds(next.slice(0, MAX_SELECTION));
      } else {
        setSelectedPaperIds(next);
      }
    },
    getCheckboxProps: (record: DepthReviewV4PaperItem) => ({
      disabled: ACTIVE_STATUSES.has(record.latest_status),
      title: ACTIVE_STATUSES.has(record.latest_status)
        ? `${record.paper_id} 正在审稿中，无法勾选`
        : "勾选后可批量重新审稿 / 删除",
    }),
  };

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: "24px 16px" }}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: 8,
          flexWrap: "wrap",
          gap: 12,
        }}
      >
        <Title level={3} style={{ margin: 0 }}>
          <FileSearch /> 深度审稿记录 (DEPTH v4.1)
        </Title>
        <Space size={8}>
          <Text type="secondary" style={{ fontSize: 13 }}>
            已选 <strong>{selectedPaperIds.length}</strong> 篇
            {selectedPaperIds.length > 0 && (
              <span style={{ marginLeft: 8 }}>（跨分页累积，后服务端统一提交）</span>
            )}
          </Text>
          <Popconfirm
            title={`确定批量重审 ${selectedPaperIds.length} 篇论文？`}
            description="将对选中的每篇论文重新发起 DEPTH v4.1 审稿任务（与单条 “重新审稿” 行为一致）"
            okText="批量重审"
            cancelText="取消"
            disabled={selectedPaperIds.length === 0 || batchReReviewing}
            onConfirm={(e) => {
              e?.stopPropagation();
              handleBatchReReview();
            }}
            onCancel={(e) => e?.stopPropagation()}
          >
            <Button
              type="primary"
              icon={<Zap />}
              loading={batchReReviewing}
              disabled={selectedPaperIds.length === 0}
              onClick={(e) => e.stopPropagation()}
            >
              批量重新审稿
            </Button>
          </Popconfirm>
          <Popconfirm
            title={`确定批量删除 ${selectedPaperIds.length} 条审稿记录？`}
            description="删除每篇论文最新一条审稿记录，此操作不可撤销"
            okText="批量删除"
            cancelText="取消"
            okButtonProps={{ danger: true }}
            disabled={selectedPaperIds.length === 0 || batchDeleting}
            onConfirm={(e) => {
              e?.stopPropagation();
              handleBatchDelete();
            }}
            onCancel={(e) => e?.stopPropagation()}
          >
            <Button
              danger
              icon={<Trash2 />}
              loading={batchDeleting}
              disabled={selectedPaperIds.length === 0}
              onClick={(e) => e.stopPropagation()}
            >
              批量删除
            </Button>
          </Popconfirm>
          <Button
            size="small"
            icon={<SquareMinus />}
            disabled={selectedPaperIds.length === 0}
            onClick={() => setSelectedPaperIds([])}
          >
            清空选择
          </Button>
        </Space>
      </div>
      <Text type="secondary" style={{ display: "block", marginBottom: 16, fontSize: 13 }}>
        按论文聚合 · 最新创新分降序 · 有正在审稿的论文每 5 秒自动刷新
      </Text>
      <Table
        dataSource={data}
        rowKey="paper_id"
        loading={loading}
        rowSelection={rowSelection}
        pagination={{
          current: page,
          total,
          pageSize: 20,
          onChange: (p) => setPage(p),
          showTotal: (t) => `共 ${t} 篇论文`,
        }}
        onRow={(record) => ({
          onClick: () => navigate(`/depth-v4/result/${record.paper_id}`),
          style: { cursor: "pointer" },
        })}
        columns={[
          {
            title: "论文",
            dataIndex: "paper_title",
            ellipsis: true,
            render: (t: string, record: DepthReviewV4PaperItem) => (
              <Space size={4} direction="vertical">
                <span>{t || "(未命名)"}</span>
                <Text
                  type="secondary"
                  style={{ fontSize: 11 }}
                  copyable={{ text: record.paper_id }}
                >
                  {record.paper_id}
                </Text>
              </Space>
            ),
          },
          {
            title: "总尝试",
            dataIndex: "total_reviews",
            width: 90,
            align: "center",
            render: (n: number, record: DepthReviewV4PaperItem) => (
              <Tooltip
                title={
                  <div>
                    <div>成功：{record.completed_count}</div>
                    <div>失败：{record.failed_count}</div>
                    <div>进行中：{record.pending_count}</div>
                  </div>
                }
              >
                <span style={{ fontWeight: 600 }}>{n}</span>
              </Tooltip>
            ),
          },
          {
            title: "失败",
            dataIndex: "failed_count",
            width: 80,
            align: "center",
            render: (n: number, record: DepthReviewV4PaperItem) =>
              n > 0 ? (
                <Tag color={record.has_unresolved_failure ? "red" : "orange"}>{n}</Tag>
              ) : (
                <Text type="secondary">-</Text>
              ),
          },
          {
            title: "最新状态",
            dataIndex: "latest_status",
            width: 110,
            render: (s: string) => (
              <Tag
                icon={STATUS_ICONS[s]}
                color={
                  s === "completed"
                    ? "green"
                    : s === "failed"
                      ? "red"
                      : s === "running"
                        ? "blue"
                        : "default"
                }
              >
                {s === "completed"
                  ? "已完成"
                  : s === "running"
                    ? "进行中"
                    : s === "failed"
                      ? "失败"
                      : "等待"}
              </Tag>
            ),
          },
          {
            title: "最新创新分",
            dataIndex: "latest_novelty_score",
            width: 120,
            render: (s: number | null) =>
              s != null ? (
                <span
                  style={{
                    fontWeight: 700,
                    color: s >= 0.7 ? "#52c41a" : s >= 0.5 ? "#faad14" : "#ff4d4f",
                  }}
                >
                  {(s * 100).toFixed(0)}%
                </span>
              ) : (
                <Text type="secondary">-</Text>
              ),
          },
          {
            title: "最新裁决",
            dataIndex: "latest_verdict",
            width: 130,
            render: (v: string | null) =>
              v ? (
                <Tag color={VERDICT_COLORS[v] || "default"}>{VERDICT_LABELS[v] || v}</Tag>
              ) : (
                <Text type="secondary">-</Text>
              ),
          },
          {
            title: "最后审稿时间",
            dataIndex: "last_attempted_at",
            width: 160,
            render: (t: string | null) => (t ? new Date(t).toLocaleString() : "-"),
          },
          {
            title: "操作",
            key: "actions",
            width: 250,
            render: (_: any, record: DepthReviewV4PaperItem) => {
              const isActive = ACTIVE_STATUSES.has(record.latest_status);
              const isRestarting = restartingIds.has(record.paper_id);
              const tip = isActive
                ? `${record.paper_id} 正在审稿中              （${record.latest_status}），请等待完成后再重审或删除`
                : record.has_unresolved_failure
                  ? `检测到 ${record.failed_count} 次失败但未成功，重审一下试试`
                  : "重新发起 DEPTH v4.1 审稿";
              return (
                <Space size={4}>
                  <Button
                    size="small"
                    onClick={(e) => {
                      e.stopPropagation();
                      navigate(`/depth-v4/result/${record.paper_id}`);
                    }}
                  >
                    查看
                  </Button>
                  <Tooltip title={tip}>
                    <Button
                      size="small"
                      type={record.has_unresolved_failure ? "primary" : "default"}
                      danger={record.has_unresolved_failure}
                      icon={<Zap />}
                      loading={isRestarting}
                      disabled={isActive}
                      onClick={(e) => {
                        e.stopPropagation();
                        handleRestartReview(record.paper_id);
                      }}
                    >
                      重新审稿
                    </Button>
                  </Tooltip>
                  <Popconfirm
                    title="确定删除该论文的最新审稿记录？"
                    description="此操作不可撤销"
                    onConfirm={(e) => {
                      e?.stopPropagation();
                      handleDelete(record.latest_record_id);
                    }}
                    onCancel={(e) => e?.stopPropagation()}
                    okText="删除"
                    cancelText="取消"
                    okButtonProps={{ danger: true }}
                  >
                    <Button
                      size="small"
                      danger
                      icon={<Trash2 />}
                      onClick={(e) => e.stopPropagation()}
                    >
                      删除
                    </Button>
                  </Popconfirm>
                </Space>
              );
            },
          },
        ]}
        expandable={{
          rowExpandable: (record) => record.total_reviews > 1 || record.failed_count > 0,
          expandedRowRender: (record) => (
            <div
              style={{ padding: "8px 16px", background: "var(--pf-bg-tertiary)", borderRadius: 6 }}
            >
              <Space size={6} wrap>
                <Tag icon={<CheckCircle />} color="green">
                  成功 {record.completed_count}
                </Tag>
                <Tag
                  icon={<XCircle />}
                  color={record.failed_count > 0 ? "red" : "default"}
                >
                  失败 {record.failed_count}
                </Tag>
                <Tag
                  icon={
                    <RefreshCw
                      className={record.latest_status === "running" ? "pf-spin" : undefined}
                    />
                  }
                  color={record.pending_count > 0 ? "blue" : "default"}
                >
                  进行中 {record.pending_count}
                </Tag>
                {record.has_unresolved_failure && (
                  <Text type="danger" style={{ fontSize: 12 }}>
                    ⚠️ 有未成功的尝试，建议重新审稿
                  </Text>
                )}
              </Space>
            </div>
          ),
        }}
      />
    </div>
  );
}

// ---- Tabs 容器（论文 v4.1 + 感悟报告） ----

/**
 * 在 /depth-v4/list 下呈现双 Tab：
 * - 论文深度审稿 (V4.1)：原 DepthListPage
 * - 感悟实验报告：ReflectionList（reflection 轻量 pipeline 评审记录）
 *
 * URL 同步：?tab=report 深度链接，缺省为 paper。
 * 设计为物理隔离，避免 v4.1 与 reflection 的字段在列表里互冲。
 */
function TabsContainer() {
  const [searchParams, setSearchParams] = useSearchParams();
  const activeTab = searchParams.get("tab") === "report" ? "report" : "paper";

  return (
    <div style={{ maxWidth: 1200, margin: "0 auto" }}>
      <Tabs
        activeKey={activeTab}
        onChange={(key) => {
          if (key === "paper") {
            // 回到 paper tab 时清除 tab 参数，保持 URL 干净
            // 【修复】不要原地修改 searchParams，必须构造新实例
            // react-router-dom v6 使用引用比较，原地修改不会触发重渲染
            const next = new URLSearchParams(searchParams);
            next.delete("tab");
            setSearchParams(next);
          } else {
            setSearchParams({ tab: key });
          }
        }}
        items={[
          {
            key: "paper",
            label: "论文深度审稿 (V4.1)",
            children: <DepthListPage />,
          },
          {
            key: "report",
            label: "感悟实验报告",
            children: <ReflectionList />,
          },
        ]}
      />
    </div>
  );
}

// ---- 路由入口 ----

export default function DepthReviewPage() {
  const { paperId } = useParams<{ paperId?: string }>();

  if (paperId) {
    return <DepthResultView paperId={paperId} />;
  }
  return <TabsContainer />;
}
